use std::{
    collections::{HashMap, HashSet},
    fs,
    path::Path,
};

use anyhow::{bail, Context};
use futures_util::TryStreamExt;
use mongodb::{
    bson::{doc, Bson, Document},
    options::ClientOptions,
    Client,
};
use roze_sqlx::{SqlxConfig, SqlxDatabaseKind, SqlxPool};
use sqlx::{AssertSqlSafe, Row};

use super::{rust_identifier, to_pascal_case, to_snake_case, GenerateMode, GenerateOptions};

const MODEL_GENERATED_MARKER: &str = "// @generated by rozectl. DO NOT EDIT.";

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ModelFormat {
    Auto,
    Ent,
    Dsl,
    Sql,
    Mongo,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ModelOrm {
    SeaOrm,
    Toasty,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum InspectDatabaseKind {
    Sqlite,
    Postgres,
    MySql,
    Mongo,
}

impl InspectDatabaseKind {
    fn as_sqlx_kind(self) -> Option<SqlxDatabaseKind> {
        match self {
            Self::Sqlite => Some(SqlxDatabaseKind::Sqlite),
            Self::Postgres => Some(SqlxDatabaseKind::Postgres),
            Self::MySql => Some(SqlxDatabaseKind::MySql),
            Self::Mongo => None,
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ModelSpec {
    pub name: String,
    pub schema_name: Option<String>,
    pub table: String,
    pub primary: String,
    pub soft_delete: Option<String>,
    pub tenant: Option<String>,
    pub cache: bool,
    pub cache_ttl_secs: Option<u64>,
    pub negative_cache_ttl_secs: Option<u64>,
    pub cache_keys: Vec<String>,
    pub cache_prefix: Option<String>,
    pub indexes: Vec<ModelIndex>,
    pub edges: Vec<ModelEdge>,
    pub fields: Vec<ModelField>,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ModelIndex {
    pub name: String,
    pub fields: Vec<String>,
    pub unique: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ModelEdge {
    pub name: String,
    pub target: String,
    pub field: String,
    pub ref_field: String,
    pub unique: bool,
    pub required: bool,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ModelField {
    pub name: String,
    pub source_name: Option<String>,
    pub ty: String,
    pub auto_increment: bool,
    pub immutable: bool,
    pub sensitive: bool,
    pub validation: ModelFieldValidation,
    pub update_default: Option<String>,
    pub client_default_value: Option<String>,
    pub default_value: Option<String>,
    pub comment: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct ModelFieldValidation {
    pub not_empty: bool,
    pub min_len: Option<usize>,
    pub max_len: Option<usize>,
    pub enum_values: Vec<String>,
    pub contains: Option<String>,
    pub starts_with: Option<String>,
    pub ends_with: Option<String>,
    pub not_contains: Option<String>,
    pub not_starts_with: Option<String>,
    pub not_ends_with: Option<String>,
    pub positive: bool,
    pub non_negative: bool,
    pub negative: bool,
    pub non_positive: bool,
    pub min: Option<String>,
    pub max: Option<String>,
}

fn normalized_source_kind(format: ModelFormat, source: &str) -> ModelFormat {
    match format {
        ModelFormat::Auto if looks_like_sql(source) => ModelFormat::Sql,
        ModelFormat::Auto if looks_like_ent(source) => ModelFormat::Ent,
        ModelFormat::Auto => ModelFormat::Dsl,
        other => other,
    }
}

fn normalize_model_source_to_ent(source: &str, format: ModelFormat) -> anyhow::Result<String> {
    match normalized_source_kind(format, source) {
        ModelFormat::Ent => Ok(source.to_string()),
        ModelFormat::Sql => Ok(render_ent_schema(&parse_sql_models(source)?)),
        ModelFormat::Dsl | ModelFormat::Mongo => Ok(render_ent_schema(&parse_dsl_models(source)?)),
        ModelFormat::Auto => unreachable!("auto model format is normalized above"),
    }
}

fn render_ent_schema(models: &[ModelSpec]) -> String {
    use std::fmt::Write as _;

    let mut out =
        String::from("// @generated by rozectl. Edit this file, then regenerate model code.\n\n");
    for model in models {
        writeln!(out, "entity {} {{", to_pascal_case(&model.name)).unwrap();
        writeln!(out, "  table {}", quote_ent_string(&model.table)).unwrap();
        if let Some(schema_name) = &model.schema_name {
            writeln!(out, "  schema {}", quote_ent_string(schema_name)).unwrap();
        }
        if model.cache {
            writeln!(out, "  cache true").unwrap();
        }
        if let Some(cache_ttl_secs) = model.cache_ttl_secs {
            writeln!(out, "  cache_ttl_secs {cache_ttl_secs}").unwrap();
        }
        if let Some(negative_cache_ttl_secs) = model.negative_cache_ttl_secs {
            writeln!(out, "  negative_cache_ttl_secs {negative_cache_ttl_secs}").unwrap();
        }
        if !model.cache_keys.is_empty() {
            writeln!(out, "  cache_key {}", model.cache_keys.join(", ")).unwrap();
        }
        if let Some(cache_prefix) = &model.cache_prefix {
            writeln!(out, "  cache_prefix {}", quote_ent_string(cache_prefix)).unwrap();
        }
        if let Some(tenant) = &model.tenant {
            writeln!(out, "  tenant {tenant}").unwrap();
        }
        if let Some(soft_delete) = &model.soft_delete {
            writeln!(out, "  soft_delete {soft_delete}").unwrap();
        }
        writeln!(out).unwrap();

        for field in &model.fields {
            let field_unique = model
                .indexes
                .iter()
                .any(|index| is_default_field_unique_index(index, &field.name))
                && !model
                    .edges
                    .iter()
                    .any(|edge| edge.unique && edge.field == field.name);
            let field_indexed = model
                .indexes
                .iter()
                .any(|index| is_default_field_index(index, &field.name));
            writeln!(
                out,
                "  field {}: {} {{",
                field.name,
                rust_type_to_ent_type(&field.ty)
            )
            .unwrap();
            if field.name == model.primary {
                writeln!(out, "    primary").unwrap();
            }
            if let Some(source_name) = &field.source_name {
                writeln!(out, "    source {}", quote_ent_string(source_name)).unwrap();
            }
            if field.auto_increment {
                writeln!(out, "    auto_increment").unwrap();
            }
            if field.immutable {
                writeln!(out, "    immutable").unwrap();
            }
            if field.sensitive {
                writeln!(out, "    sensitive").unwrap();
            }
            if field.validation.not_empty {
                writeln!(out, "    not_empty").unwrap();
            }
            if let Some(min_len) = field.validation.min_len {
                writeln!(out, "    min_len {min_len}").unwrap();
            }
            if let Some(max_len) = field.validation.max_len {
                writeln!(out, "    max_len {max_len}").unwrap();
            }
            if let Some(min) = &field.validation.min {
                writeln!(out, "    min {min}").unwrap();
            }
            if let Some(max) = &field.validation.max {
                writeln!(out, "    max {max}").unwrap();
            }
            if !field.validation.enum_values.is_empty() {
                let values = field
                    .validation
                    .enum_values
                    .iter()
                    .map(|value| quote_ent_string(value))
                    .collect::<Vec<_>>()
                    .join(", ");
                writeln!(out, "    enum {values}").unwrap();
            }
            if let Some(value) = &field.validation.contains {
                writeln!(out, "    contains {}", quote_ent_string(value)).unwrap();
            }
            if let Some(value) = &field.validation.starts_with {
                writeln!(out, "    starts_with {}", quote_ent_string(value)).unwrap();
            }
            if let Some(value) = &field.validation.ends_with {
                writeln!(out, "    ends_with {}", quote_ent_string(value)).unwrap();
            }
            if let Some(value) = &field.validation.not_contains {
                writeln!(out, "    not_contains {}", quote_ent_string(value)).unwrap();
            }
            if let Some(value) = &field.validation.not_starts_with {
                writeln!(out, "    not_starts_with {}", quote_ent_string(value)).unwrap();
            }
            if let Some(value) = &field.validation.not_ends_with {
                writeln!(out, "    not_ends_with {}", quote_ent_string(value)).unwrap();
            }
            if field.validation.positive {
                writeln!(out, "    positive").unwrap();
            }
            if field.validation.non_negative {
                writeln!(out, "    non_negative").unwrap();
            }
            if field.validation.negative {
                writeln!(out, "    negative").unwrap();
            }
            if field.validation.non_positive {
                writeln!(out, "    non_positive").unwrap();
            }
            if let Some(update_default) = &field.update_default {
                writeln!(out, "    update_default {update_default}").unwrap();
            }
            if let Some(client_default_value) = &field.client_default_value {
                writeln!(
                    out,
                    "    client_default {}",
                    quote_ent_string(client_default_value)
                )
                .unwrap();
            }
            if field_unique {
                writeln!(out, "    unique").unwrap();
            }
            if field_indexed {
                writeln!(out, "    index").unwrap();
            }
            if let Some(default_value) = &field.default_value {
                writeln!(out, "    default {}", quote_ent_string(default_value)).unwrap();
            }
            if let Some(comment) = &field.comment {
                writeln!(out, "    comment {}", quote_ent_string(comment)).unwrap();
            }
            writeln!(out, "  }}").unwrap();
            writeln!(out).unwrap();
        }

        for index in &model.indexes {
            if index
                .fields
                .first()
                .is_some_and(|field| is_default_field_unique_index(index, field))
                || index
                    .fields
                    .first()
                    .is_some_and(|field| is_default_field_index(index, field))
            {
                continue;
            }
            writeln!(out, "  index {} {{", index.name).unwrap();
            writeln!(out, "    fields {}", index.fields.join(", ")).unwrap();
            if index.unique {
                writeln!(out, "    unique").unwrap();
            }
            writeln!(out, "  }}").unwrap();
            writeln!(out).unwrap();
        }

        for edge in &model.edges {
            writeln!(out, "  edge {} {{", edge.name).unwrap();
            writeln!(out, "    to {}", to_pascal_case(&edge.target)).unwrap();
            writeln!(out, "    field {}", edge.field).unwrap();
            writeln!(out, "    ref {}", edge.ref_field).unwrap();
            if edge.unique {
                writeln!(out, "    unique").unwrap();
            }
            if edge.required {
                writeln!(out, "    required").unwrap();
            }
            writeln!(out, "  }}").unwrap();
            writeln!(out).unwrap();
        }

        writeln!(out, "}}").unwrap();
        writeln!(out).unwrap();
    }

    out
}

fn quote_ent_string(value: &str) -> String {
    format!(
        "\"{}\"",
        value
            .replace('\\', "\\\\")
            .replace('"', "\\\"")
            .replace('\n', "\\n")
    )
}

fn rust_type_to_ent_type(ty: &str) -> String {
    if let Some(inner) = optional_inner_type(ty) {
        return format!("{}?", rust_type_to_ent_type(inner));
    }
    if ty == "Vec<u8>" {
        return "bytes".to_string();
    }
    if let Some(inner) = ty
        .strip_prefix("Vec<")
        .and_then(|value| value.strip_suffix('>'))
    {
        return format!("[]{}", rust_type_to_ent_type(inner));
    }
    match ty {
        "String" => "string".to_string(),
        "rust_decimal::Decimal" => "decimal".to_string(),
        other => other.to_string(),
    }
}

pub fn generate_model_project(
    source: &str,
    out: &Path,
    options: GenerateOptions,
    format: ModelFormat,
    orm: ModelOrm,
) -> anyhow::Result<()> {
    let ent_source = normalize_model_source_to_ent(source, format)?;
    let models = parse_ent_models(&ent_source)?;
    match normalized_source_kind(format, source) {
        ModelFormat::Mongo => write_mongo_model_project(&models, out, options, &ent_source),
        _ => write_model_project(&models, out, options, orm, &ent_source),
    }
}

#[allow(clippy::too_many_arguments)]
pub async fn inspect_model_project(
    table: &str,
    schema_name: Option<&str>,
    db_url: &str,
    db_kind: InspectDatabaseKind,
    sample_size: u64,
    out: &Path,
    options: GenerateOptions,
    orm: ModelOrm,
) -> anyhow::Result<()> {
    if db_kind == InspectDatabaseKind::Mongo {
        let model = inspect_mongo_collection(table, schema_name, db_url, sample_size).await?;
        let ent_source = render_ent_schema(&[model]);
        let models = parse_ent_models(&ent_source)?;
        return write_mongo_model_project(&models, out, options, &ent_source);
    }

    let db_kind = db_kind
        .as_sqlx_kind()
        .expect("SQL inspect kind already checked");
    let pool = roze_sqlx::connect(&SqlxConfig {
        kind: db_kind,
        url: db_url.to_string(),
        max_connections: 10,
    })
    .await?;

    let model = match pool {
        SqlxPool::Sqlite(pool) => inspect_sqlite_table(&pool, schema_name, table).await?,
        SqlxPool::Postgres(pool) => inspect_postgres_table(&pool, schema_name, table).await?,
        SqlxPool::MySql(pool) => inspect_mysql_table(&pool, schema_name, table).await?,
    };

    let ent_source = render_ent_schema(&[model]);
    let models = parse_ent_models(&ent_source)?;
    write_model_project(&models, out, options, orm, &ent_source)
}

async fn inspect_mongo_collection(
    collection_name: &str,
    database_name: Option<&str>,
    db_url: &str,
    sample_size: u64,
) -> anyhow::Result<ModelSpec> {
    let mut options = ClientOptions::parse(db_url)
        .await
        .with_context(|| format!("failed to parse MongoDB URL `{db_url}`"))?;
    options
        .app_name
        .get_or_insert_with(|| "rozectl-inspect".to_string());
    let client = Client::with_options(options).context("failed to create MongoDB client")?;
    let database = if let Some(database_name) = database_name {
        client.database(database_name)
    } else {
        client.default_database().ok_or_else(|| {
            anyhow::anyhow!(
                "MongoDB inspect requires a database in --db-url or an explicit --schema <database>"
            )
        })?
    };
    let collection = database.collection::<Document>(collection_name);
    let indexes = inspect_mongo_indexes(&collection).await?;
    let limit = i64::try_from(sample_size.max(1)).unwrap_or(i64::MAX);
    let mut cursor = collection
        .find(doc! {})
        .limit(limit)
        .await
        .with_context(|| format!("failed to query MongoDB collection `{collection_name}`"))?;
    let mut documents = Vec::new();
    while let Some(document) = cursor
        .try_next()
        .await
        .with_context(|| format!("failed to read MongoDB collection `{collection_name}`"))?
    {
        documents.push(document);
    }
    validate_model_spec(model_from_mongo_documents(
        collection_name,
        &documents,
        indexes,
    ))
}

async fn inspect_mongo_indexes(
    collection: &mongodb::Collection<Document>,
) -> anyhow::Result<Vec<ModelIndex>> {
    let mut cursor = collection
        .list_indexes()
        .await
        .with_context(|| format!("failed to list MongoDB indexes for `{}`", collection.name()))?;
    let mut indexes = Vec::new();
    while let Some(index) = cursor
        .try_next()
        .await
        .with_context(|| format!("failed to read MongoDB indexes for `{}`", collection.name()))?
    {
        let fields = index
            .keys
            .keys()
            .map(|key| mongo_rust_field_name(key))
            .collect::<Vec<_>>();
        if fields.is_empty() || fields == ["id"] {
            continue;
        }
        let name = index
            .options
            .as_ref()
            .and_then(|options| options.name.clone())
            .unwrap_or_else(|| fields.join("_"));
        let unique = index
            .options
            .as_ref()
            .and_then(|options| options.unique)
            .unwrap_or(false);
        indexes.push(ModelIndex {
            name,
            fields,
            unique,
        });
    }
    Ok(indexes)
}

fn model_from_mongo_documents(
    collection_name: &str,
    documents: &[Document],
    indexes: Vec<ModelIndex>,
) -> ModelSpec {
    let mut fields = Vec::new();
    let mut seen = HashSet::new();

    if documents.is_empty()
        || documents
            .iter()
            .any(|document| document.contains_key("_id"))
    {
        fields.push(mongo_field_from_samples("_id", documents));
        seen.insert("_id".to_string());
    }

    let mut keys = documents
        .iter()
        .flat_map(|document| document.keys().cloned())
        .filter(|key| key != "_id")
        .collect::<Vec<_>>();
    keys.sort();
    keys.dedup();
    for key in keys {
        if seen.insert(key.clone()) {
            fields.push(mongo_field_from_samples(&key, documents));
        }
    }

    let primary = fields
        .iter()
        .find(|field| field.name == "id")
        .or_else(|| fields.first())
        .map(|field| field.name.clone())
        .unwrap_or_else(|| "id".to_string());
    let cache_keys = indexes
        .iter()
        .filter(|index| index.unique && index.fields.len() == 1)
        .filter_map(|index| index.fields.first())
        .filter(|field| *field != &primary)
        .cloned()
        .collect::<Vec<_>>();

    ModelSpec {
        name: to_pascal_case(collection_name),
        schema_name: None,
        table: collection_name.to_string(),
        primary,
        soft_delete: None,
        tenant: None,
        cache: false,
        cache_ttl_secs: None,
        negative_cache_ttl_secs: None,
        cache_keys,
        cache_prefix: None,
        indexes,
        edges: Vec::new(),
        fields,
    }
}

fn mongo_field_from_samples(key: &str, documents: &[Document]) -> ModelField {
    let mut observed_ty: Option<String> = None;
    let mut observed_count = 0usize;
    let mut saw_null = false;

    for document in documents {
        match document.get(key) {
            Some(Bson::Null) | Some(Bson::Undefined) => {
                saw_null = true;
                observed_count += 1;
            }
            Some(value) => {
                observed_count += 1;
                let ty = mongo_bson_type(value);
                observed_ty = Some(match observed_ty {
                    Some(existing) => merge_mongo_types(&existing, &ty),
                    None => ty,
                });
            }
            None => {}
        }
    }

    let mut ty = observed_ty.unwrap_or_else(|| {
        if key == "_id" {
            "ObjectId".to_string()
        } else {
            "bson::Bson".to_string()
        }
    });
    if key != "_id" && (saw_null || observed_count < documents.len()) && !is_optional_type(&ty) {
        ty = format!("Option<{ty}>");
    }

    ModelField {
        name: mongo_rust_field_name(key),
        source_name: Some(key.to_string()).filter(|source| source != "_id"),
        ty,
        auto_increment: false,
        immutable: false,
        sensitive: false,
        validation: ModelFieldValidation::default(),
        update_default: None,
        client_default_value: None,
        default_value: None,
        comment: None,
    }
}

fn mongo_bson_type(value: &Bson) -> String {
    match value {
        Bson::Double(_) => "f64".to_string(),
        Bson::String(_) => "String".to_string(),
        Bson::Array(values) => {
            let inner = values
                .iter()
                .map(mongo_bson_type)
                .reduce(|left, right| merge_mongo_types(&left, &right))
                .unwrap_or_else(|| "bson::Bson".to_string());
            format!("Vec<{inner}>")
        }
        Bson::Document(_) => "Document".to_string(),
        Bson::Boolean(_) => "bool".to_string(),
        Bson::ObjectId(_) => "ObjectId".to_string(),
        Bson::DateTime(_) => "DateTime".to_string(),
        Bson::Int32(_) => "i32".to_string(),
        Bson::Int64(_) => "i64".to_string(),
        Bson::Decimal128(_) => "bson::Decimal128".to_string(),
        Bson::Binary(_) => "bson::Binary".to_string(),
        Bson::Timestamp(_) => "bson::Timestamp".to_string(),
        Bson::RegularExpression(_) => "bson::Regex".to_string(),
        Bson::JavaScriptCode(_) | Bson::JavaScriptCodeWithScope(_) => "String".to_string(),
        Bson::Symbol(_) => "String".to_string(),
        Bson::Null | Bson::Undefined | Bson::DbPointer(_) | Bson::MaxKey | Bson::MinKey => {
            "bson::Bson".to_string()
        }
    }
}

fn merge_mongo_types(left: &str, right: &str) -> String {
    if left == right {
        left.to_string()
    } else if matches!((left, right), ("i32", "i64") | ("i64", "i32")) {
        "i64".to_string()
    } else if matches!(
        (left, right),
        ("i32", "f64") | ("f64", "i32") | ("i64", "f64") | ("f64", "i64")
    ) {
        "f64".to_string()
    } else {
        "bson::Bson".to_string()
    }
}

fn mongo_rust_field_name(key: &str) -> String {
    if key == "_id" {
        "id".to_string()
    } else if is_valid_rust_identifier(key) {
        key.to_string()
    } else {
        to_snake_case(key)
    }
}

fn is_valid_rust_identifier(value: &str) -> bool {
    let mut chars = value.chars();
    let Some(first) = chars.next() else {
        return false;
    };
    (first == '_' || first.is_ascii_alphabetic())
        && chars.all(|ch| ch == '_' || ch.is_ascii_alphanumeric())
}

fn write_model_project(
    models: &[ModelSpec],
    out: &Path,
    options: GenerateOptions,
    orm: ModelOrm,
    ent_source: &str,
) -> anyhow::Result<()> {
    ensure_model_output(out, options.mode)?;
    let model_dir = out.join("src/model");
    fs::create_dir_all(&model_dir)?;
    let include_client = out.join("src/svc/mod.rs").is_file();
    cleanup_stale_generated_model_files(models, &model_dir, options.mode, include_client)?;

    // Model files are schema-owned generated artifacts. Refresh them on --update
    // so database/schema changes are reflected deterministically.
    fs::write(model_dir.join("schema.ent"), ent_source)?;
    if include_client {
        fs::write(
            model_dir.join("client.rs"),
            render_model_client(models, orm),
        )?;
    }
    fs::write(
        model_dir.join("mod.rs"),
        render_model_mod(models, orm, include_client),
    )?;
    for model in models {
        let module_path = model_dir.join(format!("{}.rs", to_snake_case(&model.name)));
        let fields_path = model_dir.join(format!("{}_fields.rs", to_snake_case(&model.name)));
        let ext_path = model_dir.join(format!("{}_ext.rs", to_snake_case(&model.name)));
        let rendered = match orm {
            ModelOrm::SeaOrm => render_model_module(model),
            ModelOrm::Toasty => render_toasty_model_module(model),
        };
        fs::write(module_path, rendered)?;
        fs::write(fields_path, render_model_fields_module(model))?;
        write_model_extension(
            &ext_path,
            render_model_extension_module(model, orm),
            options.mode,
        )?;
    }

    update_model_dependencies(
        out,
        orm,
        models_need_rust_decimal(models),
        models_need_uuid(models),
    )?;
    update_model_service_context(out)?;
    if orm == ModelOrm::Toasty {
        update_toasty_service_context(out, models)?;
    }
    update_main_rs(out)?;
    Ok(())
}

fn write_mongo_model_project(
    models: &[ModelSpec],
    out: &Path,
    options: GenerateOptions,
    ent_source: &str,
) -> anyhow::Result<()> {
    ensure_model_output(out, options.mode)?;
    let model_dir = out.join("src/model");
    fs::create_dir_all(&model_dir)?;

    // Model files are schema-owned generated artifacts. Refresh them on --update
    // so database/schema changes are reflected deterministically.
    fs::write(model_dir.join("schema.ent"), ent_source)?;
    fs::write(model_dir.join("mod.rs"), render_mongo_model_mod(models))?;
    for model in models {
        let module_path = model_dir.join(format!("{}.rs", to_snake_case(&model.name)));
        fs::write(module_path, render_mongo_model_module(model))?;
    }

    update_main_rs(out)?;
    Ok(())
}

fn ensure_model_output(out: &Path, mode: GenerateMode) -> anyhow::Result<()> {
    let model_dir = out.join("src/model");
    if mode == GenerateMode::Create && model_dir.exists() && has_entries(&model_dir)? {
        bail!(
            "{} already contains generated model files; pass --update to refresh them",
            model_dir.display()
        );
    }
    Ok(())
}

fn update_main_rs(out: &Path) -> anyhow::Result<()> {
    let main_path = out.join("src/main.rs");
    if !main_path.is_file() {
        return Ok(());
    }

    let content = fs::read_to_string(&main_path)
        .with_context(|| format!("failed to read {}", main_path.display()))?;
    if content.contains("mod model;") {
        return Ok(());
    }

    let updated = insert_after_module(&content, "mod types;\n", "mod model;\n")
        .unwrap_or_else(|| format!("mod model;\n{content}"));
    fs::write(&main_path, updated)
        .with_context(|| format!("failed to write {}", main_path.display()))
}

fn update_model_dependencies(
    out: &Path,
    orm: ModelOrm,
    needs_rust_decimal: bool,
    needs_uuid: bool,
) -> anyhow::Result<()> {
    let manifest_path = out.join("Cargo.toml");
    if !manifest_path.is_file() {
        return Ok(());
    }

    let content = fs::read_to_string(&manifest_path)
        .with_context(|| format!("failed to read {}", manifest_path.display()))?;
    let mut document = content
        .parse::<toml_edit::DocumentMut>()
        .with_context(|| format!("failed to parse {}", manifest_path.display()))?;
    let dependencies = document
        .get_mut("dependencies")
        .and_then(toml_edit::Item::as_table_mut)
        .ok_or_else(|| {
            anyhow::anyhow!("{} has no [dependencies] table", manifest_path.display())
        })?;

    let dependency_name = match orm {
        ModelOrm::SeaOrm => "sea-orm",
        ModelOrm::Toasty => "toasty",
    };
    let uses_workspace = content.contains("edition.workspace = true")
        || content.contains("toasty.workspace = true")
        || content.contains("sea-orm.workspace = true")
        || content.contains("serde_json.workspace = true");

    if !dependencies.contains_key(dependency_name) {
        let item = if uses_workspace {
            workspace_dependency_item()
        } else {
            match orm {
                ModelOrm::SeaOrm => {
                    if needs_rust_decimal {
                        r#"{ version = "1", default-features = false, features = ["macros", "runtime-tokio-rustls", "sqlx-mysql", "sqlx-postgres", "sqlx-sqlite", "with-rust_decimal"] }"#
                    } else {
                        r#"{ version = "1", default-features = false, features = ["macros", "runtime-tokio-rustls", "sqlx-mysql", "sqlx-postgres", "sqlx-sqlite"] }"#
                    }
                        .parse::<toml_edit::Item>()
                        .expect("valid toml dependency value")
                }
                ModelOrm::Toasty => {
                    r#"{ version = "0.7", default-features = false, features = ["postgresql", "mysql", "serde", "rust_decimal"] }"#
                        .parse::<toml_edit::Item>()
                        .expect("valid toml dependency value")
                }
            }
        };
        dependencies.insert(dependency_name, item);
    }
    if orm == ModelOrm::SeaOrm && needs_rust_decimal {
        if let Some(item) = dependencies.get_mut("sea-orm") {
            ensure_dependency_feature(item, "with-rust_decimal");
        }
    }
    if orm == ModelOrm::Toasty {
        if let Some(item) = dependencies.get_mut("toasty") {
            ensure_dependency_feature(item, "rust_decimal");
        }
    }

    if (orm == ModelOrm::Toasty || needs_rust_decimal) && !dependencies.contains_key("rust_decimal")
    {
        let item = if uses_workspace {
            workspace_dependency_item()
        } else {
            r#"{ version = "1", features = ["serde"] }"#
                .parse::<toml_edit::Item>()
                .expect("valid toml dependency value")
        };
        dependencies.insert("rust_decimal", item);
    }

    if !dependencies.contains_key("serde_json") {
        let item = if uses_workspace {
            workspace_dependency_item()
        } else {
            r#""1""#.parse::<toml_edit::Item>().expect("valid toml dependency value")
        };
        dependencies.insert("serde_json", item);
    }
    if needs_uuid && !dependencies.contains_key("uuid") {
        let item = if uses_workspace {
            workspace_dependency_item()
        } else {
            r#"{ version = "1", features = ["v7"] }"#
                .parse::<toml_edit::Item>()
                .expect("valid toml dependency value")
        };
        dependencies.insert("uuid", item);
    }
    fs::write(&manifest_path, document.to_string())
        .with_context(|| format!("failed to write {}", manifest_path.display()))
}

fn models_need_rust_decimal(models: &[ModelSpec]) -> bool {
    models.iter().any(|model| {
        model
            .fields
            .iter()
            .any(|field| type_contains_rust_decimal(&field.ty))
    })
}

fn models_need_uuid(models: &[ModelSpec]) -> bool {
    models.iter().any(|model| {
        model.fields.iter().any(|field| {
            matches!(field.default_value.as_deref(), Some("uuid_new_string"))
                || matches!(
                    field.client_default_value.as_deref(),
                    Some("uuid_new_string")
                )
        })
    })
}

fn type_contains_rust_decimal(ty: &str) -> bool {
    ty == "rust_decimal::Decimal"
        || optional_inner_type(ty).is_some_and(|inner| inner == "rust_decimal::Decimal")
}

fn ensure_dependency_feature(item: &mut toml_edit::Item, feature: &str) {
    let Some(value) = item.as_value_mut() else {
        return;
    };
    let Some(table) = value.as_inline_table_mut() else {
        return;
    };
    let Some(features) = table.get_mut("features") else {
        return;
    };
    let Some(array) = features.as_array_mut() else {
        return;
    };
    if !array
        .iter()
        .any(|value| value.as_str().is_some_and(|value| value == feature))
    {
        array.push(feature);
    }
}

fn workspace_dependency_item() -> toml_edit::Item {
    let mut table = toml_edit::InlineTable::new();
    table.insert("workspace", true.into());
    toml_edit::Item::Value(toml_edit::Value::InlineTable(table))
}

fn update_toasty_service_context(out: &Path, models: &[ModelSpec]) -> anyhow::Result<()> {
    let svc_path = out.join("src/svc/mod.rs");
    if !svc_path.is_file() {
        return Ok(());
    }

    let content = fs::read_to_string(&svc_path)
        .with_context(|| format!("failed to read {}", svc_path.display()))?;
    if !content.contains("pub struct ServiceContext") {
        return Ok(());
    }
    let mut updated = content.replace("#[derive(Clone, Debug)]", "#[derive(Clone)]");

    let model_list = models
        .iter()
        .map(|model| format!("crate::model::{}", to_pascal_case(&model.name)))
        .collect::<Vec<_>>()
        .join(", ");
    if model_list.is_empty() {
        return Ok(());
    }

    if !updated.contains("pub toasty_db: Option<toasty::Db>") {
        updated = insert_after_module(
            &updated,
            "    pub db_connections: Option<roze_db::DatabaseConnections>,\n",
            "    pub toasty_db: Option<toasty::Db>,\n",
        )
        .or_else(|| {
            insert_after_module(
                &updated,
                "    pub health: roze_health::HealthRegistry,\n",
                "    pub toasty_db: Option<toasty::Db>,\n",
            )
        })
        .unwrap_or(updated);
    }
    if !updated.contains("let toasty_db = match config.database.as_ref()") {
        updated = insert_after_module(
            &updated,
            "        let db_connections = roze_db::connect_connections_optional(config.database.as_ref()).await?;\n",
            &format!(
                "        let toasty_db = match config.database.as_ref() {{\n            Some(database) => Some(toasty::Db::builder().models(toasty::models!({model_list})).connect(&database.url).await?),\n            None => None,\n        }};\n"
            ),
        )
        .or_else(|| {
            insert_after_module(
                &updated,
                "        let health = roze_health::HealthRegistry::new();\n",
                &format!(
                    "        let toasty_db = match config.database.as_ref() {{\n            Some(database) => Some(toasty::Db::builder().models(toasty::models!({model_list})).connect(&database.url).await?),\n            None => None,\n        }};\n"
                ),
            )
        })
        .unwrap_or(updated);
    }
    if !updated.contains("            toasty_db,\n") {
        updated = insert_after_module(
            &updated,
            "            db_connections,\n",
            "            toasty_db,\n",
        )
        .or_else(|| {
            insert_after_module(
                &updated,
                "            health,\n",
                "            toasty_db,\n",
            )
        })
        .unwrap_or(updated);
    }
    if !updated.contains("if toasty_db.is_some()") {
        updated = insert_before_module(
            &updated,
            "        health.mark_ready();\n",
            "        if toasty_db.is_some() {\n            health.register_static(roze_health::HealthCheck::healthy(\"toasty\"));\n        }\n",
        )
        .unwrap_or(updated);
    }
    let accessor = r#"    pub fn toasty_db(&self) -> anyhow::Result<toasty::Db> {
        self.toasty_db
            .clone()
            .ok_or_else(|| anyhow::anyhow!("toasty database connection is not configured"))
    }

"#;
    if !updated.contains("pub fn toasty_db(&self)") {
        updated = insert_after_read_db_method(&updated, accessor)
            .or_else(|| insert_before_module(&updated, "    pub fn jwt_config", accessor))
            .unwrap_or(updated);
    }

    fs::write(&svc_path, updated).with_context(|| format!("failed to write {}", svc_path.display()))
}

fn update_model_service_context(out: &Path) -> anyhow::Result<()> {
    let svc_path = out.join("src/svc/mod.rs");
    if !svc_path.is_file() {
        return Ok(());
    }

    let content = fs::read_to_string(&svc_path)
        .with_context(|| format!("failed to read {}", svc_path.display()))?;
    if content.contains("pub fn model(&self)") || !content.contains("pub struct ServiceContext") {
        return Ok(());
    }

    let accessor = r#"    pub fn model(&self) -> crate::model::ModelClient<'_> {
        crate::model::ModelClient::new(self)
    }

"#;
    let updated = insert_after_read_db_method(&content, accessor).unwrap_or(content);
    fs::write(&svc_path, updated).with_context(|| format!("failed to write {}", svc_path.display()))
}

fn insert_after_read_db_method(content: &str, insert: &str) -> Option<String> {
    let start = content.find("    pub fn read_db(")?;
    let body_start = content[start..].find('{')? + start;
    let mut depth = 0usize;
    for (offset, ch) in content[body_start..].char_indices() {
        match ch {
            '{' => depth += 1,
            '}' => {
                depth = depth.saturating_sub(1);
                if depth == 0 {
                    let end = body_start + offset + ch.len_utf8();
                    let newline_end = content[end..]
                        .strip_prefix("\r\n")
                        .map(|_| end + 2)
                        .or_else(|| content[end..].strip_prefix('\n').map(|_| end + 1))
                        .unwrap_or(end);
                    let mut updated = String::with_capacity(content.len() + insert.len());
                    updated.push_str(&content[..newline_end]);
                    if !content[..newline_end].ends_with("\n\n")
                        && !content[..newline_end].ends_with("\r\n\r\n")
                    {
                        updated.push('\n');
                    }
                    updated.push_str(insert);
                    updated.push_str(&content[newline_end..]);
                    return Some(updated);
                }
            }
            _ => {}
        }
    }
    None
}

fn insert_after_module(content: &str, needle: &str, insert: &str) -> Option<String> {
    let idx = content.find(needle)?;
    let mut updated = String::with_capacity(content.len() + insert.len());
    updated.push_str(&content[..idx + needle.len()]);
    updated.push_str(insert);
    updated.push_str(&content[idx + needle.len()..]);
    Some(updated)
}

fn insert_before_module(content: &str, needle: &str, insert: &str) -> Option<String> {
    let idx = content.find(needle)?;
    let mut updated = String::with_capacity(content.len() + insert.len());
    updated.push_str(&content[..idx]);
    updated.push_str(insert);
    updated.push_str(&content[idx..]);
    Some(updated)
}

fn has_entries(path: &Path) -> anyhow::Result<bool> {
    Ok(fs::read_dir(path)?.next().is_some())
}

fn cleanup_stale_generated_model_files(
    models: &[ModelSpec],
    model_dir: &Path,
    mode: GenerateMode,
    include_client: bool,
) -> anyhow::Result<()> {
    if matches!(mode, GenerateMode::Create) {
        return Ok(());
    }
    let mut expected = HashSet::from(["mod.rs".to_string()]);
    if include_client {
        expected.insert("client.rs".to_string());
    }
    for model in models {
        let module = to_snake_case(&model.name);
        expected.insert(format!("{module}.rs"));
        expected.insert(format!("{module}_fields.rs"));
    }

    for entry in fs::read_dir(model_dir)? {
        let entry = entry?;
        let path = entry.path();
        if !path.is_file() || path.extension().and_then(|ext| ext.to_str()) != Some("rs") {
            continue;
        }
        let Some(file_name) = path
            .file_name()
            .and_then(|name| name.to_str())
            .map(ToOwned::to_owned)
        else {
            continue;
        };
        if expected.contains(&file_name) || file_name.ends_with("_ext.rs") {
            continue;
        }
        let content = fs::read_to_string(&path)
            .with_context(|| format!("failed to read {}", path.display()))?;
        if content.contains(MODEL_GENERATED_MARKER) {
            fs::remove_file(&path)
                .with_context(|| format!("failed to remove stale {}", path.display()))?;
        }
    }

    Ok(())
}

fn render_model_mod(models: &[ModelSpec], orm: ModelOrm, include_client: bool) -> String {
    let mut out = format!("{MODEL_GENERATED_MARKER}\n#![allow(dead_code, unused_imports)]\n\n");
    if include_client {
        out.push_str("pub mod client;\n");
        out.push_str("pub use client::ModelClient;\n");
    }
    for model in models {
        let module = to_snake_case(&model.name);
        let fields_module = format!("{module}_fields");
        let ext_module = format!("{module}_ext");
        let pascal = to_pascal_case(&model.name);
        out.push_str(&format!("pub mod {module};\n"));
        out.push_str(&format!("pub mod {fields_module};\n"));
        out.push_str(&format!("pub mod {ext_module};\n"));
        out.push_str(&format!(
            "pub use {fields_module}::{{{pascal}Field, {}}};\n",
            table_const_name(model)
        ));
        match orm {
            ModelOrm::SeaOrm => out.push_str(&format!(
                "pub use {module}::{{{pascal}Create, {pascal}Delete, {pascal}DeleteMany, {pascal}Order, {pascal}Page, {pascal}Predicate, {pascal}Query, {pascal}Repository, {pascal}Update, {pascal}UpdateMany, ActiveModel as {pascal}ActiveModel, Entity as {pascal}Entity, Model as {pascal}Model}};\n"
            )),
            ModelOrm::Toasty => out.push_str(&format!(
                "pub use {module}::{{{pascal}, {pascal}Create, {pascal}Delete, {pascal}DeleteMany, {pascal}Order, {pascal}Page, {pascal}Predicate, {pascal}Query, {pascal}Repository, {pascal}Update, {pascal}UpdateMany}};\n"
            )),
        }
    }
    out
}

fn render_model_client(models: &[ModelSpec], orm: ModelOrm) -> String {
    let mut out = format!("{MODEL_GENERATED_MARKER}\n#![allow(dead_code, unused_imports)]\n\n");
    use std::fmt::Write as _;

    writeln!(out, "use crate::svc::ServiceContext;").unwrap();
    for model in models {
        let module = to_snake_case(&model.name);
        let pascal = to_pascal_case(&model.name);
        writeln!(out, "use super::{module}::{pascal}Repository;").unwrap();
    }
    writeln!(out).unwrap();
    writeln!(out, "pub struct ModelClient<'a> {{").unwrap();
    writeln!(out, "    ctx: &'a ServiceContext,").unwrap();
    writeln!(out, "}}").unwrap();
    writeln!(out).unwrap();
    writeln!(out, "impl<'a> ModelClient<'a> {{").unwrap();
    writeln!(out, "    pub fn new(ctx: &'a ServiceContext) -> Self {{").unwrap();
    writeln!(out, "        Self {{ ctx }}").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();
    for model in models {
        let method = model_field_ident_by_name(&to_snake_case(&model.name));
        let pascal = to_pascal_case(&model.name);
        match orm {
            ModelOrm::SeaOrm => {
                writeln!(
                    out,
                    "    pub fn {method}(&self) -> {pascal}Repository<'a> {{"
                )
                .unwrap();
                writeln!(out, "        {pascal}Repository::new(self.ctx)").unwrap();
                writeln!(out, "    }}").unwrap();
            }
            ModelOrm::Toasty => {
                writeln!(out, "    pub fn {method}(&self) -> {pascal}Repository {{").unwrap();
                writeln!(out, "        {pascal}Repository").unwrap();
                writeln!(out, "    }}").unwrap();
            }
        }
        writeln!(out).unwrap();
    }
    if orm == ModelOrm::Toasty {
        writeln!(
            out,
            "    pub fn toasty_db(&self) -> anyhow::Result<toasty::Db> {{"
        )
        .unwrap();
        writeln!(out, "        self.ctx.toasty_db()").unwrap();
        writeln!(out, "    }}").unwrap();
    }
    writeln!(out, "}}").unwrap();
    out
}

fn write_model_extension(path: &Path, content: String, mode: GenerateMode) -> anyhow::Result<()> {
    if mode == GenerateMode::Update && path.exists() {
        return Ok(());
    }
    fs::write(path, content).with_context(|| format!("failed to write {}", path.display()))
}

fn render_model_extension_module(model: &ModelSpec, orm: ModelOrm) -> String {
    let pascal = to_pascal_case(&model.name);
    let module = to_snake_case(&model.name);
    let mut out = String::new();
    use std::fmt::Write as _;

    writeln!(&mut out, "#![allow(dead_code)]").unwrap();
    writeln!(&mut out).unwrap();
    writeln!(
        &mut out,
        "// Application-owned extension methods for `{}`.",
        model.table
    )
    .unwrap();
    writeln!(
        &mut out,
        "// This file is created by rozectl but preserved during `--update`."
    )
    .unwrap();
    match orm {
        ModelOrm::SeaOrm => {
            writeln!(
                &mut out,
                "use super::{module}::{{{pascal}Repository, Model}};"
            )
            .unwrap();
        }
        ModelOrm::Toasty => {
            writeln!(
                &mut out,
                "use super::{module}::{{{pascal}, {pascal}Repository}};"
            )
            .unwrap();
        }
    }
    writeln!(&mut out).unwrap();
    match orm {
        ModelOrm::SeaOrm => {
            writeln!(&mut out, "impl Model {{").unwrap();
            writeln!(
                &mut out,
                "    // Add domain helpers for generated SeaORM model rows here."
            )
            .unwrap();
            writeln!(&mut out, "}}").unwrap();
            writeln!(&mut out).unwrap();
            writeln!(&mut out, "impl<'a> {pascal}Repository<'a> {{").unwrap();
            writeln!(
                &mut out,
                "    // Add application-owned repository queries here."
            )
            .unwrap();
            writeln!(&mut out, "}}").unwrap();
        }
        ModelOrm::Toasty => {
            writeln!(&mut out, "impl {pascal} {{").unwrap();
            writeln!(
                &mut out,
                "    // Add domain helpers for generated Toasty model rows here."
            )
            .unwrap();
            writeln!(&mut out, "}}").unwrap();
            writeln!(&mut out).unwrap();
            writeln!(&mut out, "impl {pascal}Repository {{").unwrap();
            writeln!(
                &mut out,
                "    // Add application-owned repository queries here."
            )
            .unwrap();
            writeln!(&mut out, "}}").unwrap();
        }
    }
    out
}

fn render_model_fields_module(model: &ModelSpec) -> String {
    let pascal = to_pascal_case(&model.name);
    let table_const = table_const_name(model);
    let fields_const = fields_const_name(model);
    let mut out = String::new();
    use std::fmt::Write as _;

    writeln!(&mut out, "{MODEL_GENERATED_MARKER}").unwrap();
    writeln!(&mut out, "#![allow(dead_code)]").unwrap();
    writeln!(&mut out).unwrap();
    writeln!(
        &mut out,
        "pub const {table_const}: &str = \"{}\";",
        model.table
    )
    .unwrap();
    writeln!(&mut out, "pub const {fields_const}: &[{pascal}Field] = &[").unwrap();
    for field in &model.fields {
        writeln!(
            &mut out,
            "    {pascal}Field::{},",
            to_pascal_case(&field.name)
        )
        .unwrap();
    }
    writeln!(&mut out, "];").unwrap();
    writeln!(&mut out).unwrap();
    writeln!(
        &mut out,
        "#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]"
    )
    .unwrap();
    writeln!(&mut out, "pub enum {pascal}Field {{").unwrap();
    for field in &model.fields {
        writeln!(&mut out, "    {},", to_pascal_case(&field.name)).unwrap();
    }
    writeln!(&mut out, "}}").unwrap();
    writeln!(&mut out).unwrap();
    writeln!(&mut out, "impl {pascal}Field {{").unwrap();
    writeln!(&mut out, "    pub const fn as_str(self) -> &'static str {{").unwrap();
    writeln!(&mut out, "        match self {{").unwrap();
    for field in &model.fields {
        writeln!(
            &mut out,
            "            Self::{} => \"{}\",",
            to_pascal_case(&field.name),
            field.name
        )
        .unwrap();
    }
    writeln!(&mut out, "        }}").unwrap();
    writeln!(&mut out, "    }}").unwrap();
    writeln!(&mut out, "}}").unwrap();

    out
}

fn table_const_name(model: &ModelSpec) -> String {
    format!("{}_TABLE", to_snake_case(&model.name).to_ascii_uppercase())
}

fn fields_const_name(model: &ModelSpec) -> String {
    format!("{}_FIELDS", to_snake_case(&model.name).to_ascii_uppercase())
}

fn model_field_ident(field: &ModelField) -> String {
    rust_identifier(&field.name)
}

fn model_field_ident_by_name(name: &str) -> String {
    rust_identifier(name)
}

fn has_sensitive_fields(model: &ModelSpec) -> bool {
    model.fields.iter().any(|field| field.sensitive)
}

fn render_debug_impl(out: &mut String, type_name: &str, fields: &[ModelField]) {
    use std::fmt::Write as _;

    writeln!(out, "impl std::fmt::Debug for {type_name} {{").unwrap();
    writeln!(
        out,
        "    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {{"
    )
    .unwrap();
    writeln!(
        out,
        "        let mut debug = f.debug_struct(\"{type_name}\");"
    )
    .unwrap();
    for field in fields {
        let ident = model_field_ident(field);
        if field.sensitive {
            writeln!(
                out,
                "        debug.field(\"{}\", &\"<sensitive>\");",
                field.name
            )
            .unwrap();
        } else {
            writeln!(
                out,
                "        debug.field(\"{}\", &self.{ident});",
                field.name
            )
            .unwrap();
        }
    }
    writeln!(out, "        debug.finish()").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out, "}}").unwrap();
    writeln!(out).unwrap();
}

fn render_field_validation_checks(out: &mut String, fields: &[&ModelField], result_kind: &str) {
    use std::fmt::Write as _;

    for field in fields
        .iter()
        .copied()
        .filter(|field| field.validation != ModelFieldValidation::default())
    {
        let field_ident = model_field_ident(field);
        if optional_inner_type(&field.ty).is_some() {
            writeln!(
                out,
                "        if let Some(Some(value)) = self.{field_ident}.as_ref() {{"
            )
            .unwrap();
        } else {
            writeln!(
                out,
                "        if let Some(value) = self.{field_ident}.as_ref() {{"
            )
            .unwrap();
        }
        render_field_validation_body(out, field, result_kind);
        writeln!(out, "        }}").unwrap();
    }
}

fn render_field_validation_body(out: &mut String, field: &ModelField, result_kind: &str) {
    let message_prefix = format!("{} validation failed", field.name);
    let validation_ty = optional_inner_type(&field.ty).unwrap_or(field.ty.as_str());
    if field.validation.not_empty {
        let condition = if validation_ty == "Vec<u8>" {
            "value.is_empty()"
        } else {
            "value.trim().is_empty()"
        };
        render_validation_return(
            out,
            result_kind,
            condition,
            &format!("{message_prefix}: must not be empty"),
        );
    }
    if let Some(min_len) = field.validation.min_len {
        let len_expr = if validation_ty == "Vec<u8>" {
            "value.len()"
        } else {
            "value.chars().count()"
        };
        render_validation_return(
            out,
            result_kind,
            &format!("{len_expr} < {min_len}"),
            &format!("{message_prefix}: length must be at least {min_len}"),
        );
    }
    if let Some(max_len) = field.validation.max_len {
        let len_expr = if validation_ty == "Vec<u8>" {
            "value.len()"
        } else {
            "value.chars().count()"
        };
        render_validation_return(
            out,
            result_kind,
            &format!("{len_expr} > {max_len}"),
            &format!("{message_prefix}: length must be at most {max_len}"),
        );
    }
    if !field.validation.enum_values.is_empty() {
        let allowed = field
            .validation
            .enum_values
            .iter()
            .map(|value| format!("{:?}", value))
            .collect::<Vec<_>>()
            .join(" | ");
        render_validation_return(
            out,
            result_kind,
            &format!("!matches!(value.as_str(), {allowed})"),
            &format!("{message_prefix}: value is not allowed"),
        );
    }
    if let Some(contains) = &field.validation.contains {
        render_validation_return(
            out,
            result_kind,
            &format!("!value.contains({contains:?})"),
            &format!("{message_prefix}: must contain required substring"),
        );
    }
    if let Some(starts_with) = &field.validation.starts_with {
        render_validation_return(
            out,
            result_kind,
            &format!("!value.starts_with({starts_with:?})"),
            &format!("{message_prefix}: must start with required prefix"),
        );
    }
    if let Some(ends_with) = &field.validation.ends_with {
        render_validation_return(
            out,
            result_kind,
            &format!("!value.ends_with({ends_with:?})"),
            &format!("{message_prefix}: must end with required suffix"),
        );
    }
    if let Some(not_contains) = &field.validation.not_contains {
        render_validation_return(
            out,
            result_kind,
            &format!("value.contains({not_contains:?})"),
            &format!("{message_prefix}: must not contain forbidden substring"),
        );
    }
    if let Some(not_starts_with) = &field.validation.not_starts_with {
        render_validation_return(
            out,
            result_kind,
            &format!("value.starts_with({not_starts_with:?})"),
            &format!("{message_prefix}: must not start with forbidden prefix"),
        );
    }
    if let Some(not_ends_with) = &field.validation.not_ends_with {
        render_validation_return(
            out,
            result_kind,
            &format!("value.ends_with({not_ends_with:?})"),
            &format!("{message_prefix}: must not end with forbidden suffix"),
        );
    }
    if field.validation.positive {
        render_validation_return(
            out,
            result_kind,
            "*value <= 0",
            &format!("{message_prefix}: must be positive"),
        );
    }
    if field.validation.non_negative {
        render_validation_return(
            out,
            result_kind,
            "*value < 0",
            &format!("{message_prefix}: must be non-negative"),
        );
    }
    if field.validation.negative {
        render_validation_return(
            out,
            result_kind,
            "*value >= 0",
            &format!("{message_prefix}: must be negative"),
        );
    }
    if field.validation.non_positive {
        render_validation_return(
            out,
            result_kind,
            "*value > 0",
            &format!("{message_prefix}: must be non-positive"),
        );
    }
    if let Some(min) = &field.validation.min {
        render_validation_return(
            out,
            result_kind,
            &format!("*value < {min}"),
            &format!("{message_prefix}: must be at least {min}"),
        );
    }
    if let Some(max) = &field.validation.max {
        render_validation_return(
            out,
            result_kind,
            &format!("*value > {max}"),
            &format!("{message_prefix}: must be at most {max}"),
        );
    }
}

fn render_validation_return(out: &mut String, result_kind: &str, condition: &str, message: &str) {
    use std::fmt::Write as _;

    match result_kind {
        "anyhow" => {
            writeln!(
                out,
                "            if {condition} {{ anyhow::bail!(\"{message}\"); }}"
            )
            .unwrap();
        }
        "toasty" => {
            writeln!(
                out,
                "            if {condition} {{ return Err(toasty::Error::invalid_record_count(\"{message}\")); }}"
            )
            .unwrap();
        }
        _ => unreachable!("unknown validation result kind"),
    }
}

fn render_order_shortcut_methods(out: &mut String, model: &ModelSpec, pascal: &str) {
    use std::fmt::Write as _;

    for field in model_order_fields(model) {
        let field_name = to_snake_case(&field.name);
        let asc_method = rust_identifier(&format!("order_by_{field_name}_asc"));
        let desc_method = rust_identifier(&format!("order_by_{field_name}_desc"));
        let variant = to_pascal_case(&field.name);
        writeln!(out, "    pub fn {asc_method}(mut self) -> Self {{").unwrap();
        writeln!(
            out,
            "        self.orders.push({pascal}Order::{variant}Asc);"
        )
        .unwrap();
        writeln!(out, "        self").unwrap();
        writeln!(out, "    }}").unwrap();
        writeln!(out).unwrap();
        writeln!(out, "    pub fn {desc_method}(mut self) -> Self {{").unwrap();
        writeln!(
            out,
            "        self.orders.push({pascal}Order::{variant}Desc);"
        )
        .unwrap();
        writeln!(out, "        self").unwrap();
        writeln!(out, "    }}").unwrap();
        writeln!(out).unwrap();
    }
}

fn render_update_default_assignments(out: &mut String, fields: &[&ModelField], target: &str) {
    use std::fmt::Write as _;

    for field in fields {
        if field.update_default.is_none() {
            continue;
        }
        let field_ident = model_field_ident(field);
        let Some(value_expr) = update_default_value_expr(field) else {
            continue;
        };
        match target {
            "sea-orm-active" => {
                writeln!(
                    out,
                    "        if self.{field_ident}.is_none() {{ active.{field_ident} = Set({value_expr}); }}"
                )
                .unwrap();
            }
            "toasty-model" => {
                writeln!(
                    out,
                    "        if self.{field_ident}.is_none() {{ model.{field_ident} = {value_expr}; }}"
                )
                .unwrap();
            }
            "toasty-many-model" => {
                writeln!(
                    out,
                    "            if self.{field_ident}.is_none() {{ model.{field_ident} = {value_expr}; }}"
                )
                .unwrap();
            }
            _ => unreachable!("unknown update default target"),
        }
    }
}

fn update_default_value_expr(field: &ModelField) -> Option<String> {
    let update_default = field.update_default.as_deref()?;
    timestamp_default_value_expr(update_default, &field.ty)
}

fn create_default_value_expr(field: &ModelField) -> Option<String> {
    if let Some(client_default) = field.client_default_value.as_deref() {
        return client_default_value_expr(client_default, &field.ty);
    }
    let default_value = field.default_value.as_deref()?;
    client_default_value_expr(default_value, &field.ty)
}

fn client_default_value_expr(default_value: &str, ty: &str) -> Option<String> {
    if let Some(expr) = timestamp_default_value_expr(default_value, ty) {
        return Some(expr);
    }
    if let Some(expr) = uuid_default_value_expr(default_value, ty) {
        return Some(expr);
    }
    let inner_ty = optional_inner_type(ty).unwrap_or(ty);
    if let Some(vec_inner_ty) = vec_inner_type(inner_ty) {
        let value = go_slice_default_value_expr(default_value, vec_inner_ty)?;
        return if optional_inner_type(ty).is_some() {
            Some(format!("Some({value})"))
        } else {
            Some(value)
        };
    }
    let value = match inner_ty {
        "String" => format!("{default_value:?}.to_string()"),
        "bool" if matches!(default_value, "true" | "false") => default_value.to_string(),
        ty if is_primitive_numeric_validation_type(ty) => default_value.to_string(),
        _ => return None,
    };
    if optional_inner_type(ty).is_some() {
        Some(format!("Some({value})"))
    } else {
        Some(value)
    }
}

fn go_slice_default_value_expr(default_value: &str, inner_ty: &str) -> Option<String> {
    if inner_ty == "u8" {
        if let Some(value) = go_byte_string_default_value_expr(default_value) {
            return Some(value);
        }
    }
    let (go_ty, body) = parse_go_slice_literal(default_value)?;
    if !go_slice_type_matches(go_ty, inner_ty) {
        return None;
    }
    let items = split_ent_comma_items(body).ok()?;
    if items.is_empty() {
        return Some(format!("Vec::<{inner_ty}>::new()"));
    }
    let values = items
        .iter()
        .map(|item| go_slice_item_expr(item, inner_ty))
        .collect::<Option<Vec<_>>>()?;
    Some(format!("vec![{}]", values.join(", ")))
}

fn go_byte_string_default_value_expr(default_value: &str) -> Option<String> {
    let value = default_value.trim();
    let rest = value
        .strip_prefix("[]byte(")
        .or_else(|| value.strip_prefix("[]uint8("))?;
    let raw = rest.strip_suffix(')')?.trim();
    let bytes = parse_ent_string_or_ident(raw, 0).ok()?.into_bytes();
    let values = bytes
        .iter()
        .map(u8::to_string)
        .collect::<Vec<_>>()
        .join(", ");
    Some(format!("vec![{values}]"))
}

fn parse_go_slice_literal(value: &str) -> Option<(&str, &str)> {
    let value = value.trim();
    let rest = value.strip_prefix("[]")?;
    let open = rest.rfind('{')?;
    let go_ty = rest[..open].trim();
    let body = rest[open + 1..].strip_suffix('}')?.trim();
    if go_ty.is_empty() {
        return None;
    }
    Some((go_ty, body))
}

fn go_slice_type_matches(go_ty: &str, inner_ty: &str) -> bool {
    matches!(
        (go_ty.trim(), inner_ty.trim()),
        ("string", "String")
            | ("bool", "bool")
            | ("int8", "i8")
            | ("int16", "i16")
            | ("int", "i32")
            | ("int32", "i32")
            | ("int64", "i64")
            | ("uint", "u32")
            | ("byte", "u8")
            | ("uint8", "u8")
            | ("uint16", "u16")
            | ("uint32", "u32")
            | ("uint64", "u64")
            | ("float32", "f32")
            | ("float", "f64")
            | ("float64", "f64")
    )
}

fn go_slice_item_expr(item: &str, inner_ty: &str) -> Option<String> {
    let item = item.trim();
    match inner_ty {
        "String" => parse_ent_string_or_ident(item, 0)
            .ok()
            .map(|value| format!("{value:?}.to_string()")),
        "bool" if matches!(item, "true" | "false") => Some(item.to_string()),
        "i8" => item.parse::<i8>().ok().map(|_| item.to_string()),
        "i16" => item.parse::<i16>().ok().map(|_| item.to_string()),
        "i32" => item.parse::<i32>().ok().map(|_| item.to_string()),
        "i64" => item.parse::<i64>().ok().map(|_| item.to_string()),
        "u8" => item.parse::<u8>().ok().map(|_| item.to_string()),
        "u16" => item.parse::<u16>().ok().map(|_| item.to_string()),
        "u32" => item.parse::<u32>().ok().map(|_| item.to_string()),
        "u64" => item.parse::<u64>().ok().map(|_| item.to_string()),
        "f32" => item.parse::<f32>().ok().map(|_| item.to_string()),
        "f64" => item.parse::<f64>().ok().map(|_| item.to_string()),
        _ => None,
    }
}

fn uuid_default_value_expr(default_value: &str, ty: &str) -> Option<String> {
    let inner_ty = optional_inner_type(ty).unwrap_or(ty);
    if inner_ty != "String" {
        return None;
    }
    let value = match default_value {
        "uuid_new_string" => "uuid::Uuid::now_v7().to_string()",
        _ => return None,
    };
    if optional_inner_type(ty).is_some() {
        Some(format!("Some({value})"))
    } else {
        Some(value.to_string())
    }
}

fn timestamp_default_value_expr(default_value: &str, ty: &str) -> Option<String> {
    let inner_ty = optional_inner_type(ty).unwrap_or(ty);
    let duration_getter = match default_value {
        "now_millis" => "as_millis",
        "now_secs" => "as_secs",
        "now_micros" => "as_micros",
        "now_nanos" => "as_nanos",
        _ => return None,
    };
    let value = format!(
        "std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map(|duration| duration.{duration_getter}() as {inner_ty}).unwrap_or_default()"
    );
    if optional_inner_type(ty).is_some() {
        Some(format!("Some({value})"))
    } else {
        Some(value)
    }
}

fn render_mongo_model_mod(models: &[ModelSpec]) -> String {
    let mut out = String::from("#![allow(dead_code, unused_imports)]\n\n");
    for model in models {
        let module = to_snake_case(&model.name);
        let pascal = to_pascal_case(&model.name);
        out.push_str(&format!("pub mod {module};\n"));
        out.push_str(&format!(
            "pub use {module}::{{{pascal}Repository, Model as {pascal}Model}};\n"
        ));
    }
    out
}

fn render_model_module(model: &ModelSpec) -> String {
    let pascal = to_pascal_case(&model.name);
    let primary = &model.primary;
    let primary_field = model
        .fields
        .iter()
        .find(|field| field.name == *primary)
        .expect("primary field present");
    let primary_ty = primary_field.ty.clone();
    let primary_ident = model_field_ident(primary_field);
    let table_name = &model.table;
    let cache_ttl_secs = model.cache_ttl_secs.unwrap_or(300);
    let negative_cache_ttl_secs = model
        .negative_cache_ttl_secs
        .unwrap_or_else(|| (cache_ttl_secs / 6).clamp(5, 60));
    let cache_prefix = model.cache_prefix.as_deref().unwrap_or(table_name);
    let cache_fields = cache_lookup_fields(model);
    let mut out = String::new();
    use std::fmt::Write as _;

    writeln!(&mut out, "{MODEL_GENERATED_MARKER}").unwrap();
    writeln!(&mut out, "#![allow(dead_code, unused_imports)]").unwrap();
    writeln!(&mut out).unwrap();
    writeln!(&mut out, "use std::time::Duration;").unwrap();
    writeln!(&mut out, "use sea_orm::entity::prelude::*;").unwrap();
    writeln!(
        &mut out,
        "use sea_orm::{{sea_query::{{extension::postgres::PgExpr, Condition, Expr}}, ActiveModelTrait, ColumnTrait, DatabaseConnection, DatabaseTransaction, DbErr, DeleteResult, EntityTrait, IntoActiveModel, PaginatorTrait, QueryFilter, QueryOrder, QuerySelect, Select, SelectorTrait, Set, TransactionError, TransactionTrait, UpdateResult}};"
    )
    .unwrap();
    writeln!(&mut out, "use serde::{{Deserialize, Serialize}};").unwrap();
    writeln!(&mut out).unwrap();
    writeln!(&mut out, "use crate::svc::ServiceContext;").unwrap();
    writeln!(&mut out).unwrap();
    let derive_eq = model_supports_eq(model);
    match (has_sensitive_fields(model), derive_eq) {
        (true, true) => writeln!(
            &mut out,
            "#[derive(Clone, PartialEq, Eq, Serialize, Deserialize, DeriveEntityModel)]"
        )
        .unwrap(),
        (true, false) => writeln!(
            &mut out,
            "#[derive(Clone, PartialEq, Serialize, Deserialize, DeriveEntityModel)]"
        )
        .unwrap(),
        (false, true) => writeln!(
            &mut out,
            "#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize, DeriveEntityModel)]"
        )
        .unwrap(),
        (false, false) => writeln!(
            &mut out,
            "#[derive(Clone, Debug, PartialEq, Serialize, Deserialize, DeriveEntityModel)]"
        )
        .unwrap(),
    }
    match &model.schema_name {
        Some(schema_name) => {
            writeln!(
                &mut out,
                "#[sea_orm(schema_name = \"{}\", table_name = \"{}\")]",
                schema_name, table_name
            )
            .unwrap();
        }
        None => {
            writeln!(&mut out, "#[sea_orm(table_name = \"{}\")]", table_name).unwrap();
        }
    }
    writeln!(&mut out, "pub struct Model {{").unwrap();
    for field in &model.fields {
        if field.name == model.primary {
            writeln!(&mut out, "    #[sea_orm(primary_key)]").unwrap();
        }
        if let Some(source_name) = &field.source_name {
            if source_name != &field.name {
                writeln!(
                    &mut out,
                    "    #[sea_orm(column_name = \"{}\")]",
                    source_name
                )
                .unwrap();
            }
        }
        if let Some(comment) = &field.comment {
            writeln!(&mut out, "    /// {}", comment.replace('\n', " ")).unwrap();
        }
        if let Some(default_value) = &field.default_value {
            writeln!(
                &mut out,
                "    /// default: {}",
                default_value.replace('\n', " ")
            )
            .unwrap();
        }
        writeln!(
            &mut out,
            "    pub {}: {},",
            model_field_ident(field),
            field.ty
        )
        .unwrap();
    }
    writeln!(&mut out, "}}").unwrap();
    writeln!(&mut out).unwrap();
    if has_sensitive_fields(model) {
        render_debug_impl(&mut out, "Model", &model.fields);
    }
    render_sea_orm_edge_methods(&mut out, model);
    writeln!(
        &mut out,
        "#[derive(Copy, Clone, Debug, EnumIter, DeriveRelation)]"
    )
    .unwrap();
    writeln!(&mut out, "pub enum Relation {{}}").unwrap();
    writeln!(&mut out).unwrap();
    writeln!(&mut out, "impl ActiveModelBehavior for ActiveModel {{}}").unwrap();
    writeln!(&mut out).unwrap();
    render_sea_orm_query_types(&mut out, model, &pascal);
    render_sea_orm_create_builder(&mut out, model, &pascal);
    render_sea_orm_update_builder(&mut out, model, &pascal, primary, &primary_ty);
    render_sea_orm_delete_builder(&mut out, &pascal, primary, &primary_ty);
    render_sea_orm_update_many_builder(&mut out, model, &pascal, primary, &primary_ty);
    render_sea_orm_delete_many_builder(&mut out, &pascal, primary, &primary_ty);
    render_like_pattern_helpers(&mut out, model);
    writeln!(&mut out, "pub struct {}Repository<'a> {{", pascal).unwrap();
    writeln!(&mut out, "    ctx: &'a ServiceContext,").unwrap();
    writeln!(&mut out, "}}").unwrap();
    writeln!(&mut out).unwrap();
    writeln!(&mut out, "impl<'a> {}Repository<'a> {{", pascal).unwrap();
    writeln!(
        &mut out,
        "    pub fn new(ctx: &'a ServiceContext) -> Self {{"
    )
    .unwrap();
    writeln!(&mut out, "        Self {{ ctx }}").unwrap();
    writeln!(&mut out, "    }}").unwrap();
    writeln!(&mut out).unwrap();
    writeln!(
        &mut out,
        "    fn read_db(&self) -> anyhow::Result<&DatabaseConnection> {{"
    )
    .unwrap();
    writeln!(&mut out, "        self.ctx.read_db()").unwrap();
    writeln!(&mut out, "    }}").unwrap();
    writeln!(&mut out).unwrap();
    writeln!(
        &mut out,
        "    fn write_db(&self) -> anyhow::Result<&DatabaseConnection> {{"
    )
    .unwrap();
    writeln!(&mut out, "        self.ctx.write_db()").unwrap();
    writeln!(&mut out, "    }}").unwrap();
    writeln!(&mut out).unwrap();
    render_sea_orm_transaction_method(&mut out);
    writeln!(&mut out, "    pub fn table_name() -> &'static str {{").unwrap();
    writeln!(&mut out, "        \"{}\"", table_name).unwrap();
    writeln!(&mut out, "    }}").unwrap();
    writeln!(&mut out).unwrap();
    render_sea_orm_scope_methods(&mut out, model);
    writeln!(
        &mut out,
        "    pub fn create(&self) -> {pascal}Create<'_, 'a> {{"
    )
    .unwrap();
    writeln!(&mut out, "        {pascal}Create::new(self)").unwrap();
    writeln!(&mut out, "    }}").unwrap();
    writeln!(&mut out).unwrap();
    writeln!(
        &mut out,
        "    pub fn update_one(&self, {primary_ident}: {primary_ty}) -> {pascal}Update<'_, 'a> {{"
    )
    .unwrap();
    writeln!(
        &mut out,
        "        {pascal}Update::new(self, {primary_ident})"
    )
    .unwrap();
    writeln!(&mut out, "    }}").unwrap();
    writeln!(&mut out).unwrap();
    writeln!(
        &mut out,
        "    pub fn delete_one(&self, {primary_ident}: {primary_ty}) -> {pascal}Delete<'_, 'a> {{"
    )
    .unwrap();
    writeln!(
        &mut out,
        "        {pascal}Delete::new(self, {primary_ident})"
    )
    .unwrap();
    writeln!(&mut out, "    }}").unwrap();
    writeln!(&mut out).unwrap();
    writeln!(
        &mut out,
        "    pub fn update_many(&self) -> {pascal}UpdateMany<'_, 'a> {{"
    )
    .unwrap();
    writeln!(&mut out, "        {pascal}UpdateMany::new(self)").unwrap();
    writeln!(&mut out, "    }}").unwrap();
    writeln!(&mut out).unwrap();
    writeln!(
        &mut out,
        "    pub fn delete_many(&self) -> {pascal}DeleteMany<'_, 'a> {{"
    )
    .unwrap();
    writeln!(&mut out, "        {pascal}DeleteMany::new(self)").unwrap();
    writeln!(&mut out, "    }}").unwrap();
    writeln!(&mut out).unwrap();
    render_sea_orm_query_methods(&mut out, model, &pascal, primary, &primary_ty);
    render_sea_orm_index_methods(&mut out, model);
    writeln!(
        &mut out,
        "    pub async fn find_by_{}(&self, {}: {}) -> anyhow::Result<Option<Model>> {{",
        primary, primary_ident, primary_ty
    )
    .unwrap();
    if model.cache {
        writeln!(
            &mut out,
            "        self.cached_find_by_{}({}).await",
            primary, primary_ident
        )
        .unwrap();
        writeln!(&mut out, "    }}").unwrap();
        writeln!(&mut out).unwrap();
        writeln!(
            &mut out,
            "    pub async fn find_by_{}_uncached(&self, {}: {}) -> anyhow::Result<Option<Model>> {{",
            primary, primary_ident, primary_ty
        )
        .unwrap();
    }
    writeln!(&mut out, "        let db = self.read_db()?;").unwrap();
    writeln!(
        &mut out,
        "        Ok(Entity::find_by_id({}).one(db).await?)",
        primary_ident
    )
    .unwrap();
    writeln!(&mut out, "    }}").unwrap();
    writeln!(&mut out).unwrap();
    writeln!(
        &mut out,
        "    pub async fn find_by_{}_primary(&self, {}: {}) -> anyhow::Result<Option<Model>> {{",
        primary, primary_ident, primary_ty
    )
    .unwrap();
    writeln!(&mut out, "        let db = self.write_db()?;").unwrap();
    writeln!(
        &mut out,
        "        Ok(Entity::find_by_id({}).one(db).await?)",
        primary_ident
    )
    .unwrap();
    writeln!(&mut out, "    }}").unwrap();
    writeln!(&mut out).unwrap();
    for field in cache_fields.iter().filter(|field| field.name != *primary) {
        let field_name = &field.name;
        let field_ident = model_field_ident(field);
        let field_ty = &field.ty;
        let column = to_pascal_case(field_name);
        writeln!(
            &mut out,
            "    pub async fn find_by_{}(&self, {}: {}) -> anyhow::Result<Option<Model>> {{",
            field_name, field_ident, field_ty
        )
        .unwrap();
        if model.cache {
            writeln!(
                &mut out,
                "        self.cached_find_by_{}({}).await",
                field_name, field_ident
            )
            .unwrap();
            writeln!(&mut out, "    }}").unwrap();
            writeln!(&mut out).unwrap();
            writeln!(
                &mut out,
                "    pub async fn find_by_{}_uncached(&self, {}: {}) -> anyhow::Result<Option<Model>> {{",
                field_name, field_ident, field_ty
            )
            .unwrap();
        }
        writeln!(&mut out, "        let db = self.read_db()?;").unwrap();
        writeln!(
            &mut out,
            "        Ok(Entity::find().filter(Column::{}.eq({})).one(db).await?)",
            column, field_ident
        )
        .unwrap();
        writeln!(&mut out, "    }}").unwrap();
        writeln!(&mut out).unwrap();
        writeln!(
            &mut out,
            "    pub async fn find_by_{}_primary(&self, {}: {}) -> anyhow::Result<Option<Model>> {{",
            field_name, field_ident, field_ty
        )
        .unwrap();
        writeln!(&mut out, "        let db = self.write_db()?;").unwrap();
        writeln!(
            &mut out,
            "        Ok(Entity::find().filter(Column::{}.eq({})).one(db).await?)",
            column, field_ident
        )
        .unwrap();
        writeln!(&mut out, "    }}").unwrap();
        writeln!(&mut out).unwrap();
    }
    writeln!(
        &mut out,
        "    pub async fn list(&self) -> anyhow::Result<Vec<Model>> {{"
    )
    .unwrap();
    writeln!(&mut out, "        let db = self.read_db()?;").unwrap();
    if model.soft_delete.is_some() {
        writeln!(&mut out, "        let mut select = Entity::find();").unwrap();
        writeln!(&mut out, "        select = self.apply_live_scope(select);").unwrap();
    } else {
        writeln!(&mut out, "        let select = Entity::find();").unwrap();
    }
    writeln!(&mut out, "        Ok(select.all(db).await?)").unwrap();
    writeln!(&mut out, "    }}").unwrap();
    writeln!(&mut out).unwrap();
    writeln!(
        &mut out,
        "    pub async fn insert(&self, model: Model) -> anyhow::Result<Model> {{"
    )
    .unwrap();
    writeln!(&mut out, "        let db = self.write_db()?;").unwrap();
    writeln!(
        &mut out,
        "        let active: ActiveModel = model.into_active_model();"
    )
    .unwrap();
    writeln!(&mut out, "        let inserted = active.insert(db).await?;").unwrap();
    if model.cache {
        writeln!(
            &mut out,
            "        self.invalidate_model_cache(&inserted).await?;"
        )
        .unwrap();
    }
    writeln!(&mut out, "        Ok(inserted)").unwrap();
    writeln!(&mut out, "    }}").unwrap();
    writeln!(&mut out).unwrap();
    render_sea_orm_batch_methods(&mut out, model, primary, &primary_ty);
    writeln!(
        &mut out,
        "    pub async fn update(&self, model: Model) -> anyhow::Result<Model> {{"
    )
    .unwrap();
    writeln!(&mut out, "        let db = self.write_db()?;").unwrap();
    writeln!(
        &mut out,
        "        let active: ActiveModel = model.into_active_model();"
    )
    .unwrap();
    writeln!(&mut out, "        let updated = active.update(db).await?;").unwrap();
    if model.cache {
        writeln!(
            &mut out,
            "        self.invalidate_model_cache(&updated).await?;"
        )
        .unwrap();
    }
    writeln!(&mut out, "        Ok(updated)").unwrap();
    writeln!(&mut out, "    }}").unwrap();
    writeln!(&mut out).unwrap();
    writeln!(
        &mut out,
        "    pub async fn delete_by_{}(&self, {}: {}) -> anyhow::Result<DeleteResult> {{",
        primary, primary_ident, primary_ty
    )
    .unwrap();
    writeln!(&mut out, "        let db = self.write_db()?;").unwrap();
    let primary_value_expr = sea_orm_reusable_value_expr(&primary_ty, primary_ident.as_str());
    if model.cache {
        writeln!(
            &mut out,
            "        let existing = self.find_by_{primary}_uncached({primary_value_expr}).await?;"
        )
        .unwrap();
    }
    writeln!(&mut out, "        let delete_key = {primary_value_expr};").unwrap();
    writeln!(
        &mut out,
        "        let result = Entity::delete_by_id(delete_key).exec(db).await?;"
    )
    .unwrap();
    if model.cache {
        writeln!(
            &mut out,
            "        if let Some(model) = existing.as_ref() {{"
        )
        .unwrap();
        writeln!(
            &mut out,
            "            self.invalidate_model_cache(model).await?;"
        )
        .unwrap();
        writeln!(&mut out, "        }} else {{").unwrap();
        writeln!(
            &mut out,
            "            self.invalidate_cache_field(\"{}\", &{}).await?;",
            primary, primary_ident
        )
        .unwrap();
        writeln!(&mut out, "        }}").unwrap();
    }
    writeln!(&mut out, "        Ok(result)").unwrap();
    writeln!(&mut out, "    }}").unwrap();
    render_sea_orm_soft_delete_methods(&mut out, model, primary, &primary_ty);
    if model.cache {
        writeln!(&mut out).unwrap();
        writeln!(
            &mut out,
            "    fn cache_key(&self, field: &str, value: impl std::fmt::Display) -> String {{"
        )
        .unwrap();
        writeln!(
            &mut out,
            "        format!(\"{}:{{}}:{{}}\", field, value)",
            cache_prefix
        )
        .unwrap();
        writeln!(&mut out, "    }}").unwrap();
        writeln!(&mut out).unwrap();
        writeln!(
            &mut out,
            "    async fn invalidate_model_cache(&self, model: &Model) -> anyhow::Result<()> {{"
        )
        .unwrap();
        writeln!(
            &mut out,
            "        if let Some(cache) = self.ctx.cache.as_ref() {{"
        )
        .unwrap();
        for field in &cache_fields {
            writeln!(
                &mut out,
                "            cache.del(&self.cache_key(\"{}\", &model.{})).await?;",
                field.name,
                model_field_ident(field)
            )
            .unwrap();
        }
        writeln!(&mut out, "        }}").unwrap();
        writeln!(&mut out, "        Ok(())").unwrap();
        writeln!(&mut out, "    }}").unwrap();
        writeln!(&mut out).unwrap();
        writeln!(
            &mut out,
            "    async fn invalidate_cache_field(&self, field: &str, value: impl std::fmt::Display) -> anyhow::Result<()> {{"
        )
        .unwrap();
        writeln!(
            &mut out,
            "        if let Some(cache) = self.ctx.cache.as_ref() {{"
        )
        .unwrap();
        writeln!(
            &mut out,
            "            let key = self.cache_key(field, value);"
        )
        .unwrap();
        writeln!(&mut out, "            cache.del(&key).await?;").unwrap();
        writeln!(&mut out, "        }}").unwrap();
        writeln!(&mut out, "        Ok(())").unwrap();
        writeln!(&mut out, "    }}").unwrap();
        writeln!(&mut out).unwrap();
        writeln!(
            &mut out,
            "    pub async fn cached_find_by_{}(&self, {}: {}) -> anyhow::Result<Option<Model>> {{",
            primary, primary_ident, primary_ty
        )
        .unwrap();
        writeln!(
            &mut out,
            "        if let Some(cache) = self.ctx.cache.as_ref() {{"
        )
        .unwrap();
        writeln!(
            &mut out,
            "            let key = self.cache_key(\"{}\", &{});",
            primary, primary_ident
        )
        .unwrap();
        writeln!(
            &mut out,
            "            let ttl = Duration::from_secs({});",
            cache_ttl_secs
        )
        .unwrap();
        writeln!(
            &mut out,
            "            let negative_ttl = Duration::from_secs({});",
            negative_cache_ttl_secs
        )
        .unwrap();
        writeln!(
            &mut out,
            "            let lookup = {};",
            sea_orm_reusable_value_expr(&primary_ty, primary_ident.as_str())
        )
        .unwrap();
        writeln!(&mut out, "            return cache").unwrap();
        writeln!(&mut out, "                .get_or_set_json_option(").unwrap();
        writeln!(&mut out, "                    &key,").unwrap();
        writeln!(&mut out, "                    Some(ttl),").unwrap();
        writeln!(&mut out, "                    Some(negative_ttl),").unwrap();
        writeln!(
            &mut out,
            "                    || async move {{ self.find_by_{}_uncached(lookup).await }},",
            primary
        )
        .unwrap();
        writeln!(&mut out, "                )").unwrap();
        writeln!(&mut out, "                .await;").unwrap();
        writeln!(&mut out, "        }}").unwrap();
        writeln!(&mut out).unwrap();
        writeln!(
            &mut out,
            "        self.find_by_{}_uncached({}).await",
            primary, primary_ident
        )
        .unwrap();
        writeln!(&mut out, "    }}").unwrap();
        for field in cache_fields.iter().filter(|field| field.name != *primary) {
            let field_name = &field.name;
            let field_ident = model_field_ident(field);
            let field_ty = &field.ty;
            writeln!(&mut out).unwrap();
            writeln!(
                &mut out,
                "    pub async fn cached_find_by_{}(&self, {}: {}) -> anyhow::Result<Option<Model>> {{",
                field_name, field_ident, field_ty
            )
            .unwrap();
            writeln!(
                &mut out,
                "        if let Some(cache) = self.ctx.cache.as_ref() {{"
            )
            .unwrap();
            writeln!(
                &mut out,
                "            let key = self.cache_key(\"{}\", &{});",
                field_name, field_ident
            )
            .unwrap();
            writeln!(
                &mut out,
                "            let ttl = Duration::from_secs({});",
                cache_ttl_secs
            )
            .unwrap();
            writeln!(
                &mut out,
                "            let negative_ttl = Duration::from_secs({});",
                negative_cache_ttl_secs
            )
            .unwrap();
            writeln!(
                &mut out,
                "            let lookup = {};",
                sea_orm_reusable_value_expr(field_ty, field_ident.as_str())
            )
            .unwrap();
            writeln!(&mut out, "            return cache").unwrap();
            writeln!(&mut out, "                .get_or_set_json_option(").unwrap();
            writeln!(&mut out, "                    &key,").unwrap();
            writeln!(&mut out, "                    Some(ttl),").unwrap();
            writeln!(&mut out, "                    Some(negative_ttl),").unwrap();
            writeln!(
                &mut out,
                "                    || async move {{ self.find_by_{}_uncached(lookup).await }},",
                field_name
            )
            .unwrap();
            writeln!(&mut out, "                )").unwrap();
            writeln!(&mut out, "                .await;").unwrap();
            writeln!(&mut out, "        }}").unwrap();
            writeln!(&mut out).unwrap();
            writeln!(
                &mut out,
                "        self.find_by_{}_uncached({}).await",
                field_name, field_ident
            )
            .unwrap();
            writeln!(&mut out, "    }}").unwrap();
        }
    }
    writeln!(&mut out, "}}").unwrap();

    out
}

fn render_sea_orm_transaction_method(out: &mut String) {
    use std::fmt::Write as _;
    writeln!(
        out,
        "    pub async fn transaction<F, T>(&self, func: F) -> Result<T, DbErr>"
    )
    .unwrap();
    writeln!(out, "    where").unwrap();
    writeln!(
        out,
        "        F: for<'tx> FnOnce(&'tx DatabaseTransaction) -> std::pin::Pin<Box<dyn std::future::Future<Output = Result<T, DbErr>> + Send + 'tx>> + Send,"
    )
    .unwrap();
    writeln!(out, "        T: Send,").unwrap();
    writeln!(out, "    {{").unwrap();
    writeln!(
        out,
        "        let db = self.write_db().map_err(|err| DbErr::Custom(err.to_string()))?;"
    )
    .unwrap();
    writeln!(out, "        db.transaction::<_, T, DbErr>(func)").unwrap();
    writeln!(out, "            .await").unwrap();
    writeln!(out, "            .map_err(|err| match err {{").unwrap();
    writeln!(
        out,
        "                TransactionError::Connection(err) | TransactionError::Transaction(err) => err,"
    )
    .unwrap();
    writeln!(out, "            }})").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();
}

fn render_like_pattern_helpers(out: &mut String, model: &ModelSpec) {
    if !model.fields.iter().any(is_string_filter_type) {
        return;
    }

    use std::fmt::Write as _;
    writeln!(out, "pub fn escape_like_pattern(value: &str) -> String {{").unwrap();
    writeln!(
        out,
        "    let mut escaped = String::with_capacity(value.len());"
    )
    .unwrap();
    writeln!(out, "    for ch in value.chars() {{").unwrap();
    writeln!(out, "        match ch {{").unwrap();
    writeln!(out, "            '\\\\' | '%' | '_' => {{").unwrap();
    writeln!(out, "                escaped.push('\\\\');").unwrap();
    writeln!(out, "                escaped.push(ch);").unwrap();
    writeln!(out, "            }}").unwrap();
    writeln!(out, "            _ => escaped.push(ch),").unwrap();
    writeln!(out, "        }}").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out, "    escaped").unwrap();
    writeln!(out, "}}").unwrap();
    writeln!(out).unwrap();
    writeln!(
        out,
        "pub fn contains_like_pattern(value: &str) -> String {{"
    )
    .unwrap();
    writeln!(out, "    format!(\"%{{}}%\", escape_like_pattern(value))").unwrap();
    writeln!(out, "}}").unwrap();
    writeln!(out).unwrap();
}

fn render_sea_orm_scope_methods(out: &mut String, model: &ModelSpec) {
    use std::fmt::Write as _;
    let Some(field) = model
        .soft_delete
        .as_deref()
        .and_then(|name| model.fields.iter().find(|field| field.name == name))
    else {
        return;
    };
    let column = to_pascal_case(&field.name);
    writeln!(
        out,
        "    fn apply_live_scope(&self, select: Select<Entity>) -> Select<Entity> {{"
    )
    .unwrap();
    if field.ty == "bool" {
        writeln!(out, "        select.filter(Column::{column}.eq(false))").unwrap();
    } else if is_optional_type(&field.ty) {
        writeln!(out, "        select.filter(Column::{column}.is_null())").unwrap();
    } else {
        writeln!(out, "        select").unwrap();
    }
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();
}

fn sea_orm_value_from_ref(field: &ModelField, value: &str) -> String {
    if is_copy_filter_type(&field.ty) {
        format!("*{value}")
    } else {
        format!("{value}.clone()")
    }
}

fn sea_orm_option_value_from_ref(field: &ModelField, value: &str) -> String {
    let Some(inner_ty) = optional_inner_type(&field.ty) else {
        return sea_orm_value_from_ref(field, value);
    };
    option_inner_value_from_ref(inner_ty, value)
}

fn option_inner_value_from_ref(inner_ty: &str, value: &str) -> String {
    if is_copy_filter_type(inner_ty) {
        format!("*{value}")
    } else {
        format!("{value}.clone()")
    }
}

fn option_some_value_from_ref(inner_ty: &str, value: &str) -> String {
    format!("Some({})", option_inner_value_from_ref(inner_ty, value))
}

fn option_some_vec_from_ref(inner_ty: &str, values: &str) -> String {
    if is_copy_filter_type(inner_ty) {
        format!("{values}.iter().map(|value| Some(*value)).collect::<Vec<_>>()")
    } else {
        format!("{values}.iter().cloned().map(Some).collect::<Vec<_>>()")
    }
}

fn render_sea_orm_query_types(out: &mut String, model: &ModelSpec, pascal: &str) {
    use std::fmt::Write as _;

    writeln!(
        out,
        "#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]"
    )
    .unwrap();
    writeln!(out, "pub enum {pascal}Order {{").unwrap();
    for field in model_order_fields(model) {
        let variant = to_pascal_case(&field.name);
        writeln!(out, "    {variant}Asc,").unwrap();
        writeln!(out, "    {variant}Desc,").unwrap();
    }
    writeln!(out, "}}").unwrap();
    writeln!(out).unwrap();

    writeln!(out, "#[derive(Clone, Debug, Serialize, Deserialize)]").unwrap();
    writeln!(out, "pub enum {pascal}Predicate {{").unwrap();
    for field in model_query_fields(model) {
        let field_ty = &field.ty;
        if let Some(inner_ty) = optional_inner_type(field_ty) {
            writeln!(
                out,
                "    {}({inner_ty}),",
                predicate_variant_name(field, "Eq")
            )
            .unwrap();
            writeln!(
                out,
                "    {}({inner_ty}),",
                predicate_variant_name(field, "Ne")
            )
            .unwrap();
            writeln!(out, "    {},", predicate_variant_name(field, "IsNull")).unwrap();
            writeln!(out, "    {},", predicate_variant_name(field, "IsNotNull")).unwrap();
            writeln!(
                out,
                "    {}(Vec<{inner_ty}>),",
                predicate_variant_name(field, "In")
            )
            .unwrap();
            writeln!(
                out,
                "    {}(Vec<{inner_ty}>),",
                predicate_variant_name(field, "NotIn")
            )
            .unwrap();
            if is_numeric_type(inner_ty) {
                for suffix in ["Gt", "Gte", "Lt", "Lte"] {
                    writeln!(
                        out,
                        "    {}({inner_ty}),",
                        predicate_variant_name(field, suffix)
                    )
                    .unwrap();
                }
                writeln!(
                    out,
                    "    {}({inner_ty}, {inner_ty}),",
                    predicate_variant_name(field, "Between")
                )
                .unwrap();
            }
            if inner_ty == "String" {
                for suffix in [
                    "Contains",
                    "NotContains",
                    "IContains",
                    "NotIContains",
                    "EqualFold",
                    "NotEqualFold",
                    "StartsWith",
                    "NotStartsWith",
                    "EndsWith",
                    "NotEndsWith",
                ] {
                    writeln!(
                        out,
                        "    {}(String),",
                        predicate_variant_name(field, suffix)
                    )
                    .unwrap();
                }
            }
        } else {
            writeln!(
                out,
                "    {}({field_ty}),",
                predicate_variant_name(field, "Eq")
            )
            .unwrap();
            writeln!(
                out,
                "    {}({field_ty}),",
                predicate_variant_name(field, "Ne")
            )
            .unwrap();
            writeln!(
                out,
                "    {}(Vec<{field_ty}>),",
                predicate_variant_name(field, "In")
            )
            .unwrap();
            writeln!(
                out,
                "    {}(Vec<{field_ty}>),",
                predicate_variant_name(field, "NotIn")
            )
            .unwrap();
            if is_numeric_type(field_ty) {
                for suffix in ["Gt", "Gte", "Lt", "Lte"] {
                    writeln!(
                        out,
                        "    {}({field_ty}),",
                        predicate_variant_name(field, suffix)
                    )
                    .unwrap();
                }
                writeln!(
                    out,
                    "    {}({field_ty}, {field_ty}),",
                    predicate_variant_name(field, "Between")
                )
                .unwrap();
            }
            if field_ty == "String" {
                for suffix in [
                    "Contains",
                    "NotContains",
                    "IContains",
                    "NotIContains",
                    "EqualFold",
                    "NotEqualFold",
                    "StartsWith",
                    "NotStartsWith",
                    "EndsWith",
                    "NotEndsWith",
                ] {
                    writeln!(
                        out,
                        "    {}(String),",
                        predicate_variant_name(field, suffix)
                    )
                    .unwrap();
                }
            }
        }
    }
    writeln!(out, "    And(Vec<{pascal}Predicate>),").unwrap();
    writeln!(out, "    Or(Vec<{pascal}Predicate>),").unwrap();
    writeln!(out, "    Not(Box<{pascal}Predicate>),").unwrap();
    writeln!(out, "}}").unwrap();
    writeln!(out).unwrap();

    render_toasty_predicate_helpers(out, model, pascal);

    writeln!(out, "#[derive(Clone, Debug, Serialize, Deserialize)]").unwrap();
    writeln!(out, "pub struct {pascal}Page {{").unwrap();
    writeln!(out, "    pub items: Vec<Model>,").unwrap();
    writeln!(out, "    pub total: u64,").unwrap();
    writeln!(out, "    pub page: u64,").unwrap();
    writeln!(out, "    pub page_size: u64,").unwrap();
    writeln!(out, "}}").unwrap();
    writeln!(out).unwrap();

    writeln!(out, "pub struct {pascal}Query<'repo, 'ctx> {{").unwrap();
    writeln!(out, "    repo: &'repo {pascal}Repository<'ctx>,").unwrap();
    writeln!(out, "    predicates: Vec<{pascal}Predicate>,").unwrap();
    writeln!(out, "    orders: Vec<{pascal}Order>,").unwrap();
    writeln!(out, "    limit: Option<u64>,").unwrap();
    writeln!(out, "    offset: Option<u64>,").unwrap();
    writeln!(out, "    page: Option<(u64, u64)>,").unwrap();
    if model.soft_delete.is_some() {
        writeln!(out, "    include_deleted: bool,").unwrap();
    }
    writeln!(out, "}}").unwrap();
    writeln!(out).unwrap();

    render_sea_orm_query_builder_impl(out, model, pascal);
}

fn render_sea_orm_edge_methods(out: &mut String, model: &ModelSpec) {
    use std::fmt::Write as _;

    if model.edges.is_empty() {
        return;
    }

    writeln!(out, "impl Model {{").unwrap();
    for edge in &model.edges {
        let Some(field) = model.fields.iter().find(|field| field.name == edge.field) else {
            continue;
        };
        let method = edge_query_method_name(edge);
        let target_pascal = to_pascal_case(&edge.target);
        let target_module = to_snake_case(&edge.target);
        let ref_helper = predicate_helper_name_by_name(&edge.ref_field, "eq");
        writeln!(
            out,
            "    pub async fn {method}(&self, repo: &crate::model::{target_pascal}Repository<'_>) -> anyhow::Result<Option<crate::model::{target_pascal}Model>> {{"
        )
        .unwrap();
        render_edge_value_binding(out, field);
        writeln!(
            out,
            "        repo.query().where_(crate::model::{target_module}::{ref_helper}(value)).first().await"
        )
        .unwrap();
        writeln!(out, "    }}").unwrap();
        writeln!(out).unwrap();
    }
    writeln!(out, "}}").unwrap();
    writeln!(out).unwrap();
}

fn render_sea_orm_create_builder(out: &mut String, model: &ModelSpec, pascal: &str) {
    use std::fmt::Write as _;

    writeln!(out, "pub struct {pascal}Create<'repo, 'ctx> {{").unwrap();
    writeln!(out, "    repo: &'repo {pascal}Repository<'ctx>,").unwrap();
    for field in model.fields.iter().filter(|field| !field.auto_increment) {
        let field_ident = model_field_ident(field);
        if let Some(inner_ty) = optional_inner_type(&field.ty) {
            writeln!(out, "    {field_ident}: Option<Option<{inner_ty}>>,").unwrap();
        } else {
            writeln!(out, "    {field_ident}: Option<{}>,", field.ty).unwrap();
        }
    }
    writeln!(out, "}}").unwrap();
    writeln!(out).unwrap();

    writeln!(out, "impl<'repo, 'ctx> {pascal}Create<'repo, 'ctx> {{").unwrap();
    writeln!(
        out,
        "    pub fn new(repo: &'repo {pascal}Repository<'ctx>) -> Self {{"
    )
    .unwrap();
    writeln!(out, "        Self {{").unwrap();
    writeln!(out, "            repo,").unwrap();
    for field in model.fields.iter().filter(|field| !field.auto_increment) {
        writeln!(out, "            {}: None,", model_field_ident(field)).unwrap();
    }
    writeln!(out, "        }}").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();

    for field in model.fields.iter().filter(|field| !field.auto_increment) {
        let field_ident = model_field_ident(field);
        let setter = create_setter_name(field);
        if let Some(inner_ty) = optional_inner_type(&field.ty) {
            writeln!(
                out,
                "    pub fn {setter}(mut self, value: Option<{inner_ty}>) -> Self {{"
            )
            .unwrap();
        } else {
            writeln!(
                out,
                "    pub fn {setter}(mut self, value: {}) -> Self {{",
                field.ty
            )
            .unwrap();
        }
        writeln!(out, "        self.{field_ident} = Some(value);").unwrap();
        writeln!(out, "        self").unwrap();
        writeln!(out, "    }}").unwrap();
        writeln!(out).unwrap();
    }
    render_optional_clear_methods(
        out,
        model.fields.iter().filter(|field| !field.auto_increment),
    );
    render_sea_orm_edge_builder_setters(out, model, true);

    writeln!(
        out,
        "    pub async fn save(self) -> anyhow::Result<Model> {{"
    )
    .unwrap();
    let validation_fields = model
        .fields
        .iter()
        .filter(|field| !field.auto_increment)
        .collect::<Vec<_>>();
    render_field_validation_checks(out, &validation_fields, "anyhow");
    writeln!(out, "        let db = self.repo.write_db()?;").unwrap();
    writeln!(out, "        let active = ActiveModel {{").unwrap();
    for field in model.fields.iter().filter(|field| !field.auto_increment) {
        let field_ident = model_field_ident(field);
        if optional_inner_type(&field.ty).is_some() {
            if let Some(default_expr) = create_default_value_expr(field) {
                writeln!(
                    out,
                    "            {field_ident}: self.{field_ident}.map(Set).unwrap_or_else(|| Set({default_expr})),"
                )
                .unwrap();
            } else if field.default_value.is_some() {
                writeln!(
                    out,
                    "            {field_ident}: self.{field_ident}.map(Set).unwrap_or_default(),"
                )
                .unwrap();
            } else {
                writeln!(
                    out,
                    "            {field_ident}: Set(self.{field_ident}.unwrap_or(None)),"
                )
                .unwrap();
            }
        } else if let Some(default_expr) = create_default_value_expr(field) {
            writeln!(
                out,
                "            {field_ident}: self.{field_ident}.map(Set).unwrap_or_else(|| Set({default_expr})),"
            )
            .unwrap();
        } else if field.default_value.is_some() {
            writeln!(
                out,
                "            {field_ident}: self.{field_ident}.map(Set).unwrap_or_default(),"
            )
            .unwrap();
        } else {
            writeln!(
                out,
                "            {field_ident}: Set(self.{field_ident}.ok_or_else(|| anyhow::anyhow!(\"missing required field `{field_ident}` for {pascal} create\"))?),"
            )
            .unwrap();
        }
    }
    if model.fields.iter().any(|field| field.auto_increment) {
        writeln!(out, "            ..std::default::Default::default()").unwrap();
    }
    writeln!(out, "        }};").unwrap();
    writeln!(out, "        let inserted = active.insert(db).await?;").unwrap();
    if model.cache {
        writeln!(
            out,
            "        self.repo.invalidate_model_cache(&inserted).await?;"
        )
        .unwrap();
    }
    writeln!(out, "        Ok(inserted)").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out, "}}").unwrap();
    writeln!(out).unwrap();
}

fn render_sea_orm_edge_builder_setters(out: &mut String, model: &ModelSpec, is_create: bool) {
    use std::fmt::Write as _;

    for edge in &model.edges {
        let Some(field) = model.fields.iter().find(|field| field.name == edge.field) else {
            continue;
        };
        if field.auto_increment || (!is_create && (field.name == model.primary || field.immutable))
        {
            continue;
        }
        let setter = create_setter_name_by_name(&edge.name);
        let target_pascal = to_pascal_case(&edge.target);
        let ref_ident = model_field_ident_by_name(&edge.ref_field);
        let value = edge_builder_value_expr(field, &format!("target.{ref_ident}"));
        writeln!(
            out,
            "    pub fn {setter}(mut self, target: &crate::model::{target_pascal}Model) -> Self {{"
        )
        .unwrap();
        writeln!(
            out,
            "        self.{} = Some({value});",
            model_field_ident(field)
        )
        .unwrap();
        writeln!(out, "        self").unwrap();
        writeln!(out, "    }}").unwrap();
        writeln!(out).unwrap();
        if !edge.required && optional_inner_type(&field.ty).is_some() && edge.name != field.name {
            let clear = rust_identifier(&format!("clear_{}", edge.name));
            writeln!(out, "    pub fn {clear}(mut self) -> Self {{").unwrap();
            writeln!(
                out,
                "        self.{} = Some(None);",
                model_field_ident(field)
            )
            .unwrap();
            writeln!(out, "        self").unwrap();
            writeln!(out, "    }}").unwrap();
            writeln!(out).unwrap();
        }
    }
}

fn render_sea_orm_update_builder(
    out: &mut String,
    model: &ModelSpec,
    pascal: &str,
    primary: &str,
    primary_ty: &str,
) {
    use std::fmt::Write as _;

    let primary_ident = rust_identifier(primary);
    writeln!(out, "pub struct {pascal}Update<'repo, 'ctx> {{").unwrap();
    writeln!(out, "    repo: &'repo {pascal}Repository<'ctx>,").unwrap();
    writeln!(out, "    {primary_ident}: {primary_ty},").unwrap();
    for field in updatable_model_fields(model, primary) {
        let field_ident = model_field_ident(field);
        if let Some(inner_ty) = optional_inner_type(&field.ty) {
            writeln!(out, "    {field_ident}: Option<Option<{inner_ty}>>,").unwrap();
        } else {
            writeln!(out, "    {field_ident}: Option<{}>,", field.ty).unwrap();
        }
    }
    writeln!(out, "}}").unwrap();
    writeln!(out).unwrap();

    writeln!(out, "impl<'repo, 'ctx> {pascal}Update<'repo, 'ctx> {{").unwrap();
    writeln!(
        out,
        "    pub fn new(repo: &'repo {pascal}Repository<'ctx>, {primary_ident}: {primary_ty}) -> Self {{"
    )
    .unwrap();
    writeln!(out, "        Self {{").unwrap();
    writeln!(out, "            repo,").unwrap();
    writeln!(out, "            {primary_ident},").unwrap();
    for field in updatable_model_fields(model, primary) {
        writeln!(out, "            {}: None,", model_field_ident(field)).unwrap();
    }
    writeln!(out, "        }}").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();

    for field in updatable_model_fields(model, primary) {
        let field_ident = model_field_ident(field);
        let setter = create_setter_name(field);
        if let Some(inner_ty) = optional_inner_type(&field.ty) {
            writeln!(
                out,
                "    pub fn {setter}(mut self, value: Option<{inner_ty}>) -> Self {{"
            )
            .unwrap();
        } else {
            writeln!(
                out,
                "    pub fn {setter}(mut self, value: {}) -> Self {{",
                field.ty
            )
            .unwrap();
        }
        writeln!(out, "        self.{field_ident} = Some(value);").unwrap();
        writeln!(out, "        self").unwrap();
        writeln!(out, "    }}").unwrap();
        writeln!(out).unwrap();
    }
    render_optional_clear_methods(out, updatable_model_fields(model, primary));
    render_sea_orm_edge_builder_setters(out, model, false);

    writeln!(
        out,
        "    pub async fn save(self) -> anyhow::Result<Model> {{"
    )
    .unwrap();
    let validation_fields = updatable_model_fields(model, primary);
    render_field_validation_checks(out, &validation_fields, "anyhow");
    writeln!(out, "        let db = self.repo.write_db()?;").unwrap();
    writeln!(out, "        let mut active = ActiveModel {{").unwrap();
    writeln!(
        out,
        "            {primary_ident}: Set(self.{primary_ident}),"
    )
    .unwrap();
    writeln!(out, "            ..std::default::Default::default()").unwrap();
    writeln!(out, "        }};").unwrap();
    for field in updatable_model_fields(model, primary) {
        let field_ident = model_field_ident(field);
        writeln!(
            out,
            "        if let Some(value) = self.{field_ident} {{ active.{field_ident} = Set(value); }}"
        )
        .unwrap();
    }
    let update_default_fields = updatable_model_fields(model, primary);
    render_update_default_assignments(out, &update_default_fields, "sea-orm-active");
    writeln!(out, "        let updated = active.update(db).await?;").unwrap();
    if model.cache {
        writeln!(
            out,
            "        self.repo.invalidate_model_cache(&updated).await?;"
        )
        .unwrap();
    }
    writeln!(out, "        Ok(updated)").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out, "}}").unwrap();
    writeln!(out).unwrap();
}

