fn render_sea_orm_query_methods(
    out: &mut String,
    model: &ModelSpec,
    pascal: &str,
    primary: &str,
    primary_ty: &str,
) {
    use std::fmt::Write as _;
    writeln!(out, "    pub fn query(&self) -> {pascal}Query<'_, 'a> {{").unwrap();
    writeln!(out, "        {pascal}Query::new(self)").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();
    writeln!(
        out,
        "    pub async fn count(&self) -> anyhow::Result<u64> {{"
    )
    .unwrap();
    writeln!(out, "        self.query().count().await").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();
    writeln!(
        out,
        "    pub async fn list_page(&self, page: u64, page_size: u64) -> anyhow::Result<{pascal}Page> {{"
    )
    .unwrap();
    writeln!(
        out,
        "        self.query().paginate(page, page_size).page().await"
    )
    .unwrap();
    writeln!(out, "    }}").unwrap();
    if let Some(tenant_field) = tenant_field(model) {
        writeln!(out).unwrap();
        let tenant_ident = model_field_ident(tenant_field);
        let primary_helper = predicate_helper_name(
            model
                .fields
                .iter()
                .find(|field| field.name == primary)
                .expect("primary field present"),
            "eq",
        );
        let tenant_helper = predicate_helper_name(tenant_field, "eq");
        writeln!(
            out,
            "    pub async fn find_by_{primary}_for_{}(&self, {primary}: {primary_ty}, {}: {}) -> anyhow::Result<Option<Model>> {{",
            tenant_field.name, tenant_ident, tenant_field.ty
        )
        .unwrap();
        writeln!(
            out,
            "        self.query().where_({primary_helper}({primary})).where_({tenant_helper}({tenant_ident})).first().await"
        )
        .unwrap();
        writeln!(out, "    }}").unwrap();
    }
    writeln!(out).unwrap();
}

fn render_sea_orm_query_builder_impl(out: &mut String, model: &ModelSpec, pascal: &str) {
    use std::fmt::Write as _;

    writeln!(out, "impl<'repo, 'ctx> {pascal}Query<'repo, 'ctx> {{").unwrap();
    writeln!(
        out,
        "    pub fn new(repo: &'repo {pascal}Repository<'ctx>) -> Self {{"
    )
    .unwrap();
    writeln!(out, "        Self {{").unwrap();
    writeln!(out, "            repo,").unwrap();
    writeln!(out, "            predicates: Vec::new(),").unwrap();
    writeln!(out, "            orders: Vec::new(),").unwrap();
    writeln!(out, "            limit: None,").unwrap();
    writeln!(out, "            offset: None,").unwrap();
    writeln!(out, "            page: None,").unwrap();
    if model.soft_delete.is_some() {
        writeln!(out, "            include_deleted: false,").unwrap();
    }
    writeln!(out, "        }}").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();
    writeln!(
        out,
        "    pub fn where_(mut self, predicate: {pascal}Predicate) -> Self {{"
    )
    .unwrap();
    writeln!(out, "        self.predicates.push(predicate);").unwrap();
    writeln!(out, "        self").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();
    writeln!(
        out,
        "    pub fn where_all<I>(mut self, predicates: I) -> Self"
    )
    .unwrap();
    writeln!(out, "    where").unwrap();
    writeln!(out, "        I: IntoIterator<Item = {pascal}Predicate>,").unwrap();
    writeln!(out, "    {{").unwrap();
    writeln!(out, "        self.predicates.extend(predicates);").unwrap();
    writeln!(out, "        self").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();
    writeln!(
        out,
        "    pub fn where_any<I>(mut self, predicates: I) -> Self"
    )
    .unwrap();
    writeln!(out, "    where").unwrap();
    writeln!(out, "        I: IntoIterator<Item = {pascal}Predicate>,").unwrap();
    writeln!(out, "    {{").unwrap();
    writeln!(
        out,
        "        let predicates = predicates.into_iter().collect::<Vec<_>>();"
    )
    .unwrap();
    writeln!(out, "        if !predicates.is_empty() {{").unwrap();
    writeln!(
        out,
        "            self.predicates.push({pascal}Predicate::Or(predicates));"
    )
    .unwrap();
    writeln!(out, "        }}").unwrap();
    writeln!(out, "        self").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();
    writeln!(
        out,
        "    pub fn where_not(mut self, predicate: {pascal}Predicate) -> Self {{"
    )
    .unwrap();
    writeln!(
        out,
        "        self.predicates.push({pascal}Predicate::Not(Box::new(predicate)));"
    )
    .unwrap();
    writeln!(out, "        self").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();
    writeln!(
        out,
        "    pub fn where_none<I>(mut self, predicates: I) -> Self"
    )
    .unwrap();
    writeln!(out, "    where").unwrap();
    writeln!(out, "        I: IntoIterator<Item = {pascal}Predicate>,").unwrap();
    writeln!(out, "    {{").unwrap();
    writeln!(
        out,
        "        let predicates = predicates.into_iter().collect::<Vec<_>>();"
    )
    .unwrap();
    writeln!(out, "        if !predicates.is_empty() {{").unwrap();
    writeln!(
        out,
        "            self.predicates.push({pascal}Predicate::Not(Box::new({pascal}Predicate::Or(predicates))));"
    )
    .unwrap();
    writeln!(out, "        }}").unwrap();
    writeln!(out, "        self").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();
    writeln!(
        out,
        "    pub fn order(mut self, order: {pascal}Order) -> Self {{"
    )
    .unwrap();
    writeln!(out, "        self.orders.push(order);").unwrap();
    writeln!(out, "        self").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();
    writeln!(out, "    pub fn order_all<I>(mut self, orders: I) -> Self").unwrap();
    writeln!(out, "    where").unwrap();
    writeln!(out, "        I: IntoIterator<Item = {pascal}Order>,").unwrap();
    writeln!(out, "    {{").unwrap();
    writeln!(out, "        self.orders.extend(orders);").unwrap();
    writeln!(out, "        self").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();
    render_order_shortcut_methods(out, model, pascal);
    writeln!(out, "    pub fn limit(mut self, limit: u64) -> Self {{").unwrap();
    writeln!(out, "        self.limit = Some(limit);").unwrap();
    writeln!(out, "        self").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();
    writeln!(out, "    pub fn offset(mut self, offset: u64) -> Self {{").unwrap();
    writeln!(out, "        self.offset = Some(offset);").unwrap();
    writeln!(out, "        self").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();
    writeln!(
        out,
        "    pub fn paginate(mut self, page: u64, page_size: u64) -> Self {{"
    )
    .unwrap();
    writeln!(out, "        self.page = Some((page, page_size));").unwrap();
    writeln!(out, "        self").unwrap();
    writeln!(out, "    }}").unwrap();
    if model.soft_delete.is_some() {
        writeln!(out).unwrap();
        writeln!(out, "    pub fn with_deleted(mut self) -> Self {{").unwrap();
        writeln!(out, "        self.include_deleted = true;").unwrap();
        writeln!(out, "        self").unwrap();
        writeln!(out, "    }}").unwrap();
    }
    writeln!(out).unwrap();

    render_sea_orm_predicate_expr(out, model, pascal);
    render_sea_orm_build_select_methods(out, model, pascal);
    render_sea_orm_query_execute_methods(out, model, pascal);
    writeln!(out, "}}").unwrap();
    writeln!(out).unwrap();
}

fn render_sea_orm_predicate_expr(out: &mut String, model: &ModelSpec, pascal: &str) {
    use std::fmt::Write as _;

    writeln!(
        out,
        "    fn predicate_condition(predicate: &{pascal}Predicate) -> Condition {{"
    )
    .unwrap();
    writeln!(out, "        match predicate {{").unwrap();
    for field in model_query_fields(model) {
        let column = to_pascal_case(&field.name);
        if let Some(inner_ty) = optional_inner_type(&field.ty) {
            let eq_value = sea_orm_option_value_from_ref(field, "value");
            let values = option_some_vec_from_ref(inner_ty, "values");
            writeln!(
                out,
                "            {pascal}Predicate::{}(value) => Condition::all().add(Column::{column}.eq(Some({eq_value}))),",
                predicate_variant_name(field, "Eq")
            )
            .unwrap();
            writeln!(
                out,
                "            {pascal}Predicate::{}(value) => Condition::all().add(Column::{column}.ne(Some({eq_value}))),",
                predicate_variant_name(field, "Ne")
            )
            .unwrap();
            writeln!(
                out,
                "            {pascal}Predicate::{} => Condition::all().add(Column::{column}.is_null()),",
                predicate_variant_name(field, "IsNull")
            )
            .unwrap();
            writeln!(
                out,
                "            {pascal}Predicate::{} => Condition::all().add(Column::{column}.is_not_null()),",
                predicate_variant_name(field, "IsNotNull")
            )
            .unwrap();
            writeln!(
                out,
                "            {pascal}Predicate::{}(values) => Condition::all().add(Column::{column}.is_in({values})),",
                predicate_variant_name(field, "In")
            )
            .unwrap();
            writeln!(
                out,
                "            {pascal}Predicate::{}(values) => Condition::all().add(Column::{column}.is_not_in({values})),",
                predicate_variant_name(field, "NotIn")
            )
            .unwrap();
            if is_numeric_type(inner_ty) {
                for (suffix, op) in [("Gt", "gt"), ("Gte", "gte"), ("Lt", "lt"), ("Lte", "lte")] {
                    let value = option_some_value_from_ref(inner_ty, "value");
                    writeln!(
                        out,
                        "            {pascal}Predicate::{}(value) => Condition::all().add(Column::{column}.{op}({value})),",
                        predicate_variant_name(field, suffix)
                    )
                    .unwrap();
                }
                let start = option_some_value_from_ref(inner_ty, "start");
                let end = option_some_value_from_ref(inner_ty, "end");
                writeln!(
                    out,
                    "            {pascal}Predicate::{}(start, end) => Condition::all().add(Column::{column}.between({start}, {end})),",
                    predicate_variant_name(field, "Between")
                )
                .unwrap();
            }
            if is_string_filter_type(field) {
                writeln!(
                    out,
                    "            {pascal}Predicate::{}(value) => Condition::all().add(Column::{column}.like(contains_like_pattern(value))),",
                    predicate_variant_name(field, "Contains")
                )
                .unwrap();
                writeln!(
                    out,
                    "            {pascal}Predicate::{}(value) => Condition::all().add(Column::{column}.like(contains_like_pattern(value))).not(),",
                    predicate_variant_name(field, "NotContains")
                )
                .unwrap();
                writeln!(
                    out,
                    "            {pascal}Predicate::{}(value) => Condition::all().add(Expr::col(Column::{column}).ilike(contains_like_pattern(value))),",
                    predicate_variant_name(field, "IContains")
                )
                .unwrap();
                writeln!(
                    out,
                    "            {pascal}Predicate::{}(value) => Condition::all().add(Expr::col(Column::{column}).ilike(contains_like_pattern(value))).not(),",
                    predicate_variant_name(field, "NotIContains")
                )
                .unwrap();
                writeln!(
                    out,
                    "            {pascal}Predicate::{}(value) => Condition::all().add(Expr::col(Column::{column}).ilike(escape_like_pattern(value))),",
                    predicate_variant_name(field, "EqualFold")
                )
                .unwrap();
                writeln!(
                    out,
                    "            {pascal}Predicate::{}(value) => Condition::all().add(Expr::col(Column::{column}).ilike(escape_like_pattern(value))).not(),",
                    predicate_variant_name(field, "NotEqualFold")
                )
                .unwrap();
                writeln!(
                    out,
                    "            {pascal}Predicate::{}(value) => Condition::all().add(Column::{column}.like(format!(\"{{}}%\", escape_like_pattern(value)))),",
                    predicate_variant_name(field, "StartsWith")
                )
                .unwrap();
                writeln!(
                    out,
                    "            {pascal}Predicate::{}(value) => Condition::all().add(Column::{column}.like(format!(\"{{}}%\", escape_like_pattern(value)))).not(),",
                    predicate_variant_name(field, "NotStartsWith")
                )
                .unwrap();
                writeln!(
                    out,
                    "            {pascal}Predicate::{}(value) => Condition::all().add(Column::{column}.like(format!(\"%{{}}\", escape_like_pattern(value)))),",
                    predicate_variant_name(field, "EndsWith")
                )
                .unwrap();
                writeln!(
                    out,
                    "            {pascal}Predicate::{}(value) => Condition::all().add(Column::{column}.like(format!(\"%{{}}\", escape_like_pattern(value)))).not(),",
                    predicate_variant_name(field, "NotEndsWith")
                )
                .unwrap();
            }
        } else {
            let value = sea_orm_value_from_ref(field, "value");
            writeln!(
                out,
                "            {pascal}Predicate::{}(value) => Condition::all().add(Column::{column}.eq({value})),",
                predicate_variant_name(field, "Eq")
            )
            .unwrap();
            writeln!(
                out,
                "            {pascal}Predicate::{}(value) => Condition::all().add(Column::{column}.ne({value})),",
                predicate_variant_name(field, "Ne")
            )
            .unwrap();
            writeln!(
                out,
                "            {pascal}Predicate::{}(values) => Condition::all().add(Column::{column}.is_in(values.clone())),",
                predicate_variant_name(field, "In")
            )
            .unwrap();
            writeln!(
                out,
                "            {pascal}Predicate::{}(values) => Condition::all().add(Column::{column}.is_not_in(values.clone())),",
                predicate_variant_name(field, "NotIn")
            )
            .unwrap();
            if is_numeric_type(&field.ty) {
                for (suffix, op) in [("Gt", "gt"), ("Gte", "gte"), ("Lt", "lt"), ("Lte", "lte")] {
                    let value = sea_orm_value_from_ref(field, "value");
                    writeln!(
                        out,
                        "            {pascal}Predicate::{}(value) => Condition::all().add(Column::{column}.{op}({value})),",
                        predicate_variant_name(field, suffix)
                    )
                    .unwrap();
                }
                let start = sea_orm_value_from_ref(field, "start");
                let end = sea_orm_value_from_ref(field, "end");
                writeln!(
                    out,
                    "            {pascal}Predicate::{}(start, end) => Condition::all().add(Column::{column}.between({start}, {end})),",
                    predicate_variant_name(field, "Between")
                )
                .unwrap();
            }
            if is_string_filter_type(field) {
                writeln!(
                    out,
                    "            {pascal}Predicate::{}(value) => Condition::all().add(Column::{column}.like(contains_like_pattern(value))),",
                    predicate_variant_name(field, "Contains")
                )
                .unwrap();
                writeln!(
                    out,
                    "            {pascal}Predicate::{}(value) => Condition::all().add(Column::{column}.like(contains_like_pattern(value))).not(),",
                    predicate_variant_name(field, "NotContains")
                )
                .unwrap();
                writeln!(
                    out,
                    "            {pascal}Predicate::{}(value) => Condition::all().add(Expr::col(Column::{column}).ilike(contains_like_pattern(value))),",
                    predicate_variant_name(field, "IContains")
                )
                .unwrap();
                writeln!(
                    out,
                    "            {pascal}Predicate::{}(value) => Condition::all().add(Expr::col(Column::{column}).ilike(contains_like_pattern(value))).not(),",
                    predicate_variant_name(field, "NotIContains")
                )
                .unwrap();
                writeln!(
                    out,
                    "            {pascal}Predicate::{}(value) => Condition::all().add(Expr::col(Column::{column}).ilike(escape_like_pattern(value))),",
                    predicate_variant_name(field, "EqualFold")
                )
                .unwrap();
                writeln!(
                    out,
                    "            {pascal}Predicate::{}(value) => Condition::all().add(Expr::col(Column::{column}).ilike(escape_like_pattern(value))).not(),",
                    predicate_variant_name(field, "NotEqualFold")
                )
                .unwrap();
                writeln!(
                    out,
                    "            {pascal}Predicate::{}(value) => Condition::all().add(Column::{column}.like(format!(\"{{}}%\", escape_like_pattern(value)))),",
                    predicate_variant_name(field, "StartsWith")
                )
                .unwrap();
                writeln!(
                    out,
                    "            {pascal}Predicate::{}(value) => Condition::all().add(Column::{column}.like(format!(\"{{}}%\", escape_like_pattern(value)))).not(),",
                    predicate_variant_name(field, "NotStartsWith")
                )
                .unwrap();
                writeln!(
                    out,
                    "            {pascal}Predicate::{}(value) => Condition::all().add(Column::{column}.like(format!(\"%{{}}\", escape_like_pattern(value)))),",
                    predicate_variant_name(field, "EndsWith")
                )
                .unwrap();
                writeln!(
                    out,
                    "            {pascal}Predicate::{}(value) => Condition::all().add(Column::{column}.like(format!(\"%{{}}\", escape_like_pattern(value)))).not(),",
                    predicate_variant_name(field, "NotEndsWith")
                )
                .unwrap();
            }
        }
    }
    writeln!(
        out,
        "            {pascal}Predicate::And(predicates) => predicates.iter().fold(Condition::all(), |condition, predicate| condition.add(Self::predicate_condition(predicate))),"
    )
    .unwrap();
    writeln!(
        out,
        "            {pascal}Predicate::Or(predicates) => predicates.iter().fold(Condition::any(), |condition, predicate| condition.add(Self::predicate_condition(predicate))),"
    )
    .unwrap();
    writeln!(
        out,
        "            {pascal}Predicate::Not(predicate) => Condition::all().add(Self::predicate_condition(predicate)).not(),"
    )
    .unwrap();
    writeln!(out, "        }}").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();
}

fn render_sea_orm_build_select_methods(out: &mut String, model: &ModelSpec, pascal: &str) {
    use std::fmt::Write as _;

    writeln!(
        out,
        "    fn build_filter_select(&self) -> Select<Entity> {{"
    )
    .unwrap();
    writeln!(out, "        let mut select = Entity::find();").unwrap();
    if model.soft_delete.is_some() {
        writeln!(
            out,
            "        if !self.include_deleted {{ select = self.repo.apply_live_scope(select); }}"
        )
        .unwrap();
    }
    writeln!(
        out,
        "        for predicate in &self.predicates {{ select = select.filter(Self::predicate_condition(predicate)); }}"
    )
    .unwrap();
    writeln!(out, "        select").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();

    writeln!(
        out,
        "    fn apply_order(&self, mut select: Select<Entity>) -> Select<Entity> {{"
    )
    .unwrap();
    writeln!(out, "        for order in &self.orders {{").unwrap();
    writeln!(out, "            match order {{").unwrap();
    for field in model_order_fields(model) {
        let variant = to_pascal_case(&field.name);
        writeln!(
            out,
            "                {pascal}Order::{variant}Asc => select = select.order_by_asc(Column::{variant}),"
        )
        .unwrap();
        writeln!(
            out,
            "                {pascal}Order::{variant}Desc => select = select.order_by_desc(Column::{variant}),"
        )
        .unwrap();
    }
    writeln!(out, "            }}").unwrap();
    writeln!(out, "        }}").unwrap();
    writeln!(out, "        select").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();

    writeln!(out, "    fn build_select(&self) -> Select<Entity> {{").unwrap();
    writeln!(
        out,
        "        let mut select = self.apply_order(self.build_filter_select());"
    )
    .unwrap();
    writeln!(
        out,
        "        if let Some(limit) = self.limit {{ select = select.limit(limit); }}"
    )
    .unwrap();
    writeln!(
        out,
        "        if let Some(offset) = self.offset {{ select = select.offset(offset); }}"
    )
    .unwrap();
    writeln!(out, "        select").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();
}

fn render_sea_orm_query_execute_methods(out: &mut String, model: &ModelSpec, pascal: &str) {
    use std::fmt::Write as _;

    writeln!(
        out,
        "    pub async fn count(self) -> anyhow::Result<u64> {{"
    )
    .unwrap();
    writeln!(out, "        let db = self.repo.read_db()?;").unwrap();
    writeln!(
        out,
        "        Ok(self.build_filter_select().count(db).await?)"
    )
    .unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();

    writeln!(
        out,
        "    pub async fn exists(self) -> anyhow::Result<bool> {{"
    )
    .unwrap();
    writeln!(out, "        Ok(self.count().await? > 0)").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();

    writeln!(
        out,
        "    pub async fn all(self) -> anyhow::Result<Vec<Model>> {{"
    )
    .unwrap();
    writeln!(out, "        let db = self.repo.read_db()?;").unwrap();
    writeln!(out, "        Ok(self.build_select().all(db).await?)").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();

    let primary_field = model
        .fields
        .iter()
        .find(|field| field.name == model.primary)
        .expect("primary field present");
    let primary_column = to_pascal_case(&primary_field.name);
    writeln!(
        out,
        "    pub async fn ids(self) -> anyhow::Result<Vec<{}>> {{",
        primary_field.ty
    )
    .unwrap();
    writeln!(out, "        let db = self.repo.read_db()?;").unwrap();
    writeln!(
        out,
        "        Ok(self.build_select().select_only().column(Column::{primary_column}).into_tuple::<{}>().all(db).await?)",
        primary_field.ty
    )
    .unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();
    writeln!(
        out,
        "    pub async fn first_id(mut self) -> anyhow::Result<Option<{}>> {{",
        primary_field.ty
    )
    .unwrap();
    writeln!(out, "        self.limit = Some(1);").unwrap();
    writeln!(out, "        Ok(self.ids().await?.into_iter().next())").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();
    writeln!(
        out,
        "    pub async fn only_id(mut self) -> anyhow::Result<{}> {{",
        primary_field.ty
    )
    .unwrap();
    writeln!(out, "        self.limit = Some(2);").unwrap();
    writeln!(out, "        let mut ids = self.ids().await?;").unwrap();
    writeln!(out, "        match ids.len() {{").unwrap();
    writeln!(out, "            1 => Ok(ids.remove(0)),").unwrap();
    writeln!(
        out,
        "            0 => anyhow::bail!(\"expected exactly one {pascal} id, found none\"),"
    )
    .unwrap();
    writeln!(
        out,
        "            _ => anyhow::bail!(\"expected exactly one {pascal} id, found multiple\"),"
    )
    .unwrap();
    writeln!(out, "        }}").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();

    for field in &model.fields {
        let method = rust_identifier(&format!("pluck_{}", field.name));
        let column = to_pascal_case(&field.name);
        writeln!(
            out,
            "    pub async fn {method}(self) -> anyhow::Result<Vec<{}>> {{",
            field.ty
        )
        .unwrap();
        writeln!(out, "        let db = self.repo.read_db()?;").unwrap();
        writeln!(
            out,
            "        Ok(self.build_select().select_only().column(Column::{column}).into_tuple::<{}>().all(db).await?)",
            field.ty
        )
        .unwrap();
        writeln!(out, "    }}").unwrap();
        writeln!(out).unwrap();

        if group_count_return_type(&field.ty).is_some() {
            let count_method = rust_identifier(&format!("count_by_{}", field.name));
            writeln!(
                out,
                "    pub async fn {count_method}(self) -> anyhow::Result<Vec<({}, u64)>> {{",
                field.ty
            )
            .unwrap();
            writeln!(
                out,
                "        let mut groups = std::collections::BTreeMap::new();"
            )
            .unwrap();
            writeln!(out, "        for value in self.{method}().await? {{").unwrap();
            writeln!(out, "            *groups.entry(value).or_insert(0) += 1;").unwrap();
            writeln!(out, "        }}").unwrap();
            writeln!(out, "        Ok(groups.into_iter().collect())").unwrap();
            writeln!(out, "    }}").unwrap();
            writeln!(out).unwrap();

            let unique_method = rust_identifier(&format!("unique_{}", field.name));
            writeln!(
                out,
                "    pub async fn {unique_method}(self) -> anyhow::Result<Vec<{}>> {{",
                field.ty
            )
            .unwrap();
            writeln!(
                out,
                "        let values = self.{method}().await?.into_iter().collect::<std::collections::BTreeSet<_>>();"
            )
            .unwrap();
            writeln!(out, "        Ok(values.into_iter().collect())").unwrap();
            writeln!(out, "    }}").unwrap();
            writeln!(out).unwrap();
        }

        if field.name != model.primary {
            let first_method = rust_identifier(&format!("first_{}", field.name));
            let only_method = rust_identifier(&format!("only_{}", field.name));
            writeln!(
                out,
                "    pub async fn {first_method}(mut self) -> anyhow::Result<Option<{}>> {{",
                field.ty
            )
            .unwrap();
            writeln!(out, "        self.limit = Some(1);").unwrap();
            writeln!(out, "        Ok(self.{method}().await?.into_iter().next())").unwrap();
            writeln!(out, "    }}").unwrap();
            writeln!(out).unwrap();
            writeln!(
                out,
                "    pub async fn {only_method}(mut self) -> anyhow::Result<{}> {{",
                field.ty
            )
            .unwrap();
            writeln!(out, "        self.limit = Some(2);").unwrap();
            writeln!(out, "        let mut values = self.{method}().await?;").unwrap();
            writeln!(out, "        match values.len() {{").unwrap();
            writeln!(out, "            1 => Ok(values.remove(0)),").unwrap();
            writeln!(
                out,
                "            0 => anyhow::bail!(\"expected exactly one {pascal}.{} value, found none\"),",
                field.name
            )
            .unwrap();
            writeln!(
                out,
                "            _ => anyhow::bail!(\"expected exactly one {pascal}.{} value, found multiple\"),",
                field.name
            )
            .unwrap();
            writeln!(out, "        }}").unwrap();
            writeln!(out, "    }}").unwrap();
            writeln!(out).unwrap();
        }
    }

    for field in model
        .fields
        .iter()
        .filter(|field| sum_return_type(&field.ty).is_some())
    {
        let method = rust_identifier(&format!("sum_{}", field.name));
        let pluck_method = rust_identifier(&format!("pluck_{}", field.name));
        let sum_ty = sum_return_type(&field.ty).expect("sum type");
        writeln!(
            out,
            "    pub async fn {method}(self) -> anyhow::Result<{sum_ty}> {{"
        )
        .unwrap();
        writeln!(out, "        let values = self.{pluck_method}().await?;").unwrap();
        if optional_inner_type(&field.ty).is_some() {
            writeln!(out, "        Ok(values.into_iter().flatten().sum())").unwrap();
        } else {
            writeln!(out, "        Ok(values.into_iter().sum())").unwrap();
        }
        writeln!(out, "    }}").unwrap();
        writeln!(out).unwrap();
    }

    for field in model
        .fields
        .iter()
        .filter(|field| avg_return_type(&field.ty).is_some())
    {
        let method = rust_identifier(&format!("avg_{}", field.name));
        let pluck_method = rust_identifier(&format!("pluck_{}", field.name));
        let avg_ty = avg_return_type(&field.ty).expect("avg type");
        writeln!(
            out,
            "    pub async fn {method}(self) -> anyhow::Result<Option<{avg_ty}>> {{"
        )
        .unwrap();
        writeln!(out, "        let values = self.{pluck_method}().await?;").unwrap();
        render_avg_body(out, &field.ty, "anyhow");
        writeln!(out, "    }}").unwrap();
        writeln!(out).unwrap();
    }

    for field in model
        .fields
        .iter()
        .filter(|field| sum_return_type(&field.ty).is_some())
    {
        let min_method = rust_identifier(&format!("min_{}", field.name));
        let max_method = rust_identifier(&format!("max_{}", field.name));
        let pluck_method = rust_identifier(&format!("pluck_{}", field.name));
        let aggregate_ty = sum_return_type(&field.ty).expect("aggregate type");
        writeln!(
            out,
            "    pub async fn {min_method}(self) -> anyhow::Result<Option<{aggregate_ty}>> {{"
        )
        .unwrap();
        writeln!(out, "        let values = self.{pluck_method}().await?;").unwrap();
        if optional_inner_type(&field.ty).is_some() {
            writeln!(out, "        Ok(values.into_iter().flatten().reduce(|left, right| if left <= right {{ left }} else {{ right }}))").unwrap();
        } else {
            writeln!(out, "        Ok(values.into_iter().reduce(|left, right| if left <= right {{ left }} else {{ right }}))").unwrap();
        }
        writeln!(out, "    }}").unwrap();
        writeln!(out).unwrap();
        writeln!(
            out,
            "    pub async fn {max_method}(self) -> anyhow::Result<Option<{aggregate_ty}>> {{"
        )
        .unwrap();
        writeln!(out, "        let values = self.{pluck_method}().await?;").unwrap();
        if optional_inner_type(&field.ty).is_some() {
            writeln!(out, "        Ok(values.into_iter().flatten().reduce(|left, right| if left >= right {{ left }} else {{ right }}))").unwrap();
        } else {
            writeln!(out, "        Ok(values.into_iter().reduce(|left, right| if left >= right {{ left }} else {{ right }}))").unwrap();
        }
        writeln!(out, "    }}").unwrap();
        writeln!(out).unwrap();
    }
    writeln!(
        out,
        "    pub async fn first(self) -> anyhow::Result<Option<Model>> {{"
    )
    .unwrap();
    writeln!(out, "        let db = self.repo.read_db()?;").unwrap();
    writeln!(out, "        Ok(self.build_select().one(db).await?)").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();

    writeln!(
        out,
        "    pub async fn only(mut self) -> anyhow::Result<Model> {{"
    )
    .unwrap();
    writeln!(out, "        self.limit = Some(2);").unwrap();
    writeln!(out, "        let mut items = self.all().await?;").unwrap();
    writeln!(out, "        match items.len() {{").unwrap();
    writeln!(out, "            1 => Ok(items.remove(0)),").unwrap();
    writeln!(
        out,
        "            0 => anyhow::bail!(\"expected exactly one {pascal} row, found none\"),"
    )
    .unwrap();
    writeln!(
        out,
        "            _ => anyhow::bail!(\"expected exactly one {pascal} row, found multiple\"),"
    )
    .unwrap();
    writeln!(out, "        }}").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();

    writeln!(
        out,
        "    pub async fn page(self) -> anyhow::Result<{pascal}Page> {{"
    )
    .unwrap();
    writeln!(out, "        let db = self.repo.read_db()?;").unwrap();
    writeln!(
        out,
        "        let (page, page_size) = self.page.unwrap_or((1, 20));"
    )
    .unwrap();
    writeln!(
        out,
        "        let page = if page == 0 {{ 1 }} else {{ page }};"
    )
    .unwrap();
    writeln!(
        out,
        "        let page_size = if page_size == 0 {{ 20 }} else {{ page_size.min(500) }};"
    )
    .unwrap();
    writeln!(
        out,
        "        let total = self.build_filter_select().count(db).await?;"
    )
    .unwrap();
    writeln!(
        out,
        "        let paginator = self.build_select().paginate(db, page_size);"
    )
    .unwrap();
    writeln!(
        out,
        "        let items = paginator.fetch_page(page.saturating_sub(1)).await?;"
    )
    .unwrap();
    writeln!(
        out,
        "        Ok({pascal}Page {{ items, total, page, page_size }})"
    )
    .unwrap();
    writeln!(out, "    }}").unwrap();
}

fn render_sea_orm_index_methods(out: &mut String, model: &ModelSpec) {
    use std::fmt::Write as _;
    for index in model
        .indexes
        .iter()
        .filter(|index| index.fields.len() > 1 || !index.unique)
    {
        let Some(fields) = index_fields(model, index) else {
            continue;
        };
        let suffix = index_method_suffix(index);
        let args = fields
            .iter()
            .map(|field| format!("{}: {}", model_field_ident(field), field.ty))
            .collect::<Vec<_>>()
            .join(", ");
        let predicates = fields
            .iter()
            .map(|field| {
                format!(
                    ".where_({}({}))",
                    predicate_helper_name(field, "eq"),
                    model_field_ident(field)
                )
            })
            .collect::<String>();
        writeln!(out).unwrap();
        if index.unique {
            writeln!(
                out,
                "    pub async fn find_by_{suffix}(&self, {args}) -> anyhow::Result<Option<Model>> {{"
            )
            .unwrap();
            writeln!(out, "        self.query(){predicates}.first().await").unwrap();
            writeln!(out, "    }}").unwrap();
        } else {
            writeln!(
                out,
                "    pub async fn list_by_{suffix}(&self, {args}) -> anyhow::Result<Vec<Model>> {{"
            )
            .unwrap();
            writeln!(out, "        self.query(){predicates}.all().await").unwrap();
            writeln!(out, "    }}").unwrap();
        }
    }
}

fn render_sea_orm_batch_methods(
    out: &mut String,
    model: &ModelSpec,
    primary: &str,
    primary_ty: &str,
) {
    use std::fmt::Write as _;
    let primary_column = to_pascal_case(primary);
    writeln!(
        out,
        "    pub async fn insert_many(&self, models: Vec<Model>) -> anyhow::Result<()> {{"
    )
    .unwrap();
    writeln!(out, "        if models.is_empty() {{ return Ok(()); }}").unwrap();
    writeln!(out, "        let db = self.write_db()?;").unwrap();
    writeln!(
        out,
        "        let active_models = models.into_iter().map(IntoActiveModel::into_active_model).collect::<Vec<_>>();"
    )
    .unwrap();
    writeln!(
        out,
        "        Entity::insert_many(active_models).exec(db).await?;"
    )
    .unwrap();
    writeln!(out, "        Ok(())").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();
    writeln!(
        out,
        "    pub async fn delete_many_by_ids(&self, ids: Vec<{primary_ty}>) -> anyhow::Result<DeleteResult> {{"
    )
    .unwrap();
    writeln!(
        out,
        "        if ids.is_empty() {{ return Ok(DeleteResult {{ rows_affected: 0 }}); }}"
    )
    .unwrap();
    writeln!(out, "        let db = self.write_db()?;").unwrap();
    writeln!(
        out,
        "        let result = Entity::delete_many().filter(Column::{primary_column}.is_in(ids.clone())).exec(db).await?;"
    )
    .unwrap();
    if model.cache {
        writeln!(out, "        for id in ids {{").unwrap();
        writeln!(
            out,
            "            self.invalidate_cache_field(\"{primary}\", &id).await?;"
        )
        .unwrap();
        writeln!(out, "        }}").unwrap();
    }
    writeln!(out, "        Ok(result)").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();
}

fn render_sea_orm_soft_delete_methods(
    out: &mut String,
    model: &ModelSpec,
    primary: &str,
    primary_ty: &str,
) {
    use std::fmt::Write as _;
    let Some(field) = model
        .soft_delete
        .as_deref()
        .and_then(|name| model.fields.iter().find(|field| field.name == name))
    else {
        return;
    };
    let primary_column = to_pascal_case(primary);
    let soft_column = to_pascal_case(&field.name);
    let primary_ident = model
        .fields
        .iter()
        .find(|field| field.name == primary)
        .map(model_field_ident)
        .unwrap_or_else(|| model_field_ident_by_name(primary));
    writeln!(out).unwrap();
    writeln!(
        out,
        "    pub async fn soft_delete_by_{primary}(&self, {primary_ident}: {primary_ty}) -> anyhow::Result<UpdateResult> {{"
    )
    .unwrap();
    writeln!(out, "        let db = self.write_db()?;").unwrap();
    let primary_value_expr = sea_orm_reusable_value_expr(primary_ty, primary_ident.as_str());
    writeln!(
        out,
        "        let mut update = Entity::update_many().filter(Column::{primary_column}.eq({primary_value_expr}));"
    )
    .unwrap();
    render_soft_delete_assignment(out, field, &soft_column);
    writeln!(out, "        let result = update.exec(db).await?;").unwrap();
    if model.cache {
        writeln!(
            out,
            "        self.invalidate_cache_field(\"{primary}\", &{primary_ident}).await?;"
        )
        .unwrap();
    }
    writeln!(out, "        Ok(result)").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();
    writeln!(
        out,
        "    pub async fn soft_delete_many_by_ids(&self, ids: Vec<{primary_ty}>) -> anyhow::Result<UpdateResult> {{"
    )
    .unwrap();
    writeln!(
        out,
        "        if ids.is_empty() {{ return Ok(UpdateResult {{ rows_affected: 0 }}); }}"
    )
    .unwrap();
    writeln!(out, "        let db = self.write_db()?;").unwrap();
    writeln!(
        out,
        "        let mut update = Entity::update_many().filter(Column::{primary_column}.is_in(ids.clone()));"
    )
    .unwrap();
    render_soft_delete_assignment(out, field, &soft_column);
    writeln!(out, "        let result = update.exec(db).await?;").unwrap();
    if model.cache {
        writeln!(out, "        for id in ids {{").unwrap();
        writeln!(
            out,
            "            self.invalidate_cache_field(\"{primary}\", &id).await?;"
        )
        .unwrap();
        writeln!(out, "        }}").unwrap();
    }
    writeln!(out, "        Ok(result)").unwrap();
    writeln!(out, "    }}").unwrap();
}

fn render_soft_delete_assignment(out: &mut String, field: &ModelField, column: &str) {
    use std::fmt::Write as _;
    if field.ty == "bool" {
        writeln!(
            out,
            "        update = update.col_expr(Column::{column}, Expr::value(true));"
        )
        .unwrap();
    } else if field.ty == "Option<String>" {
        writeln!(
            out,
            "        update = update.col_expr(Column::{column}, Expr::value(Some(format!(\"{{:?}}\", std::time::SystemTime::now()))));"
        )
        .unwrap();
    } else if field.ty == "Option<i64>" || field.ty == "Option<u64>" {
        writeln!(
            out,
            "        update = update.col_expr(Column::{column}, Expr::value(Some(std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map(|duration| duration.as_millis() as {}).unwrap_or_default())));",
            field.ty.trim_start_matches("Option<").trim_end_matches('>')
        )
        .unwrap();
    } else {
        writeln!(
            out,
            "        update = update.col_expr(Column::{column}, Expr::value(Default::default()));"
        )
        .unwrap();
    }
}

fn model_query_fields(model: &ModelSpec) -> Vec<&ModelField> {
    model
        .fields
        .iter()
        .filter(|field| Some(field.name.as_str()) != model.soft_delete.as_deref())
        .collect()
}

fn model_order_fields(model: &ModelSpec) -> Vec<&ModelField> {
    model_query_fields(model)
}

fn updatable_model_fields<'a>(model: &'a ModelSpec, primary: &str) -> Vec<&'a ModelField> {
    model
        .fields
        .iter()
        .filter(|field| field.name != primary && !field.immutable)
        .collect()
}

fn is_string_filter_type(field: &ModelField) -> bool {
    field.ty == "String" || optional_inner_type(&field.ty).is_some_and(|inner| inner == "String")
}

fn tenant_field(model: &ModelSpec) -> Option<&ModelField> {
    model
        .tenant
        .as_deref()
        .and_then(|name| model.fields.iter().find(|field| field.name == name))
}

fn index_fields<'a>(model: &'a ModelSpec, index: &ModelIndex) -> Option<Vec<&'a ModelField>> {
    index
        .fields
        .iter()
        .map(|name| model.fields.iter().find(|field| field.name == *name))
        .collect()
}

fn index_method_suffix(index: &ModelIndex) -> String {
    index.fields.join("_and_")
}

fn predicate_variant_name(field: &ModelField, suffix: &str) -> String {
    format!("{}{}", to_pascal_case(&field.name), suffix)
}

fn predicate_helper_name(field: &ModelField, suffix: &str) -> String {
    rust_identifier(&format!("{}_{}", field.name, suffix))
}

fn predicate_helper_name_by_name(field_name: &str, suffix: &str) -> String {
    rust_identifier(&format!("{field_name}_{suffix}"))
}

fn edge_has_helper_name(edge: &ModelEdge) -> String {
    rust_identifier(&format!("has_{}", edge.name))
}

fn edge_not_has_helper_name(edge: &ModelEdge) -> String {
    rust_identifier(&format!("not_has_{}", edge.name))
}

fn edge_query_method_name(edge: &ModelEdge) -> String {
    rust_identifier(&format!("query_{}", edge.name))
}

fn render_edge_value_binding(out: &mut String, field: &ModelField) {
    use std::fmt::Write as _;

    let field_ident = model_field_ident(field);
    if let Some(inner_ty) = optional_inner_type(&field.ty) {
        let value = if is_copy_filter_type(inner_ty) {
            "*value".to_string()
        } else {
            "value.clone()".to_string()
        };
        writeln!(
            out,
            "        let Some(value) = self.{field_ident}.as_ref() else {{ return Ok(None); }};"
        )
        .unwrap();
        writeln!(out, "        let value = {value};").unwrap();
    } else if is_copy_filter_type(&field.ty) {
        writeln!(out, "        let value = self.{field_ident};").unwrap();
    } else {
        writeln!(out, "        let value = self.{field_ident}.clone();").unwrap();
    }
}

fn create_setter_name(field: &ModelField) -> String {
    create_setter_name_by_name(&field.name)
}

fn create_setter_name_by_name(name: &str) -> String {
    rust_identifier(&format!("set_{name}"))
}

fn clear_setter_name(field: &ModelField) -> String {
    rust_identifier(&format!("clear_{}", field.name))
}

fn render_optional_clear_methods<'a, I>(out: &mut String, fields: I)
where
    I: IntoIterator<Item = &'a ModelField>,
{
    use std::fmt::Write as _;

    for field in fields {
        if optional_inner_type(&field.ty).is_none() {
            continue;
        }
        let field_ident = model_field_ident(field);
        let clear = clear_setter_name(field);
        writeln!(out, "    pub fn {clear}(mut self) -> Self {{").unwrap();
        writeln!(out, "        self.{field_ident} = Some(None);").unwrap();
        writeln!(out, "        self").unwrap();
        writeln!(out, "    }}").unwrap();
        writeln!(out).unwrap();
    }
}

fn render_predicate_group_builder_methods(out: &mut String, pascal: &str) {
    use std::fmt::Write as _;

    writeln!(
        out,
        "    pub fn where_all<I>(mut self, predicates: I) -> Self"
    )
    .unwrap();
    writeln!(out, "    where").unwrap();
    writeln!(out, "        I: IntoIterator<Item = {pascal}Predicate>,").unwrap();
    writeln!(out, "    {{").unwrap();
    writeln!(out, "        self.predicates.extend(predicates);").unwrap();
    writeln!(out, "        self").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();
    writeln!(
        out,
        "    pub fn where_any<I>(mut self, predicates: I) -> Self"
    )
    .unwrap();
    writeln!(out, "    where").unwrap();
    writeln!(out, "        I: IntoIterator<Item = {pascal}Predicate>,").unwrap();
    writeln!(out, "    {{").unwrap();
    writeln!(
        out,
        "        let predicates = predicates.into_iter().collect::<Vec<_>>();"
    )
    .unwrap();
    writeln!(out, "        if !predicates.is_empty() {{").unwrap();
    writeln!(
        out,
        "            self.predicates.push({pascal}Predicate::Or(predicates));"
    )
    .unwrap();
    writeln!(out, "        }}").unwrap();
    writeln!(out, "        self").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();
    writeln!(
        out,
        "    pub fn where_not(mut self, predicate: {pascal}Predicate) -> Self {{"
    )
    .unwrap();
    writeln!(
        out,
        "        self.predicates.push({pascal}Predicate::Not(Box::new(predicate)));"
    )
    .unwrap();
    writeln!(out, "        self").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();
    writeln!(
        out,
        "    pub fn where_none<I>(mut self, predicates: I) -> Self"
    )
    .unwrap();
    writeln!(out, "    where").unwrap();
    writeln!(out, "        I: IntoIterator<Item = {pascal}Predicate>,").unwrap();
    writeln!(out, "    {{").unwrap();
    writeln!(
        out,
        "        let predicates = predicates.into_iter().collect::<Vec<_>>();"
    )
    .unwrap();
    writeln!(out, "        if !predicates.is_empty() {{").unwrap();
    writeln!(
        out,
        "            self.predicates.push({pascal}Predicate::Not(Box::new({pascal}Predicate::Or(predicates))));"
    )
    .unwrap();
    writeln!(out, "        }}").unwrap();
    writeln!(out, "        self").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();
}

fn edge_builder_value_expr(field: &ModelField, value: &str) -> String {
    if let Some(inner_ty) = optional_inner_type(&field.ty) {
        let inner = if is_copy_filter_type(inner_ty) {
            value.to_string()
        } else {
            format!("{value}.clone()")
        };
        format!("Some({inner})")
    } else if is_copy_filter_type(&field.ty) {
        value.to_string()
    } else {
        format!("{value}.clone()")
    }
}

fn toasty_value_from_ref(field: &ModelField, value: &str) -> String {
    if is_copy_filter_type(&field.ty) {
        format!("*{value}")
    } else {
        format!("{value}.clone()")
    }
}

fn toasty_option_value_from_ref(field: &ModelField, value: &str) -> String {
    let Some(inner_ty) = optional_inner_type(&field.ty) else {
        return toasty_value_from_ref(field, value);
    };
    option_inner_value_from_ref(inner_ty, value)
}

fn update_slot_value_from_ref(field: &ModelField, value: &str) -> String {
    if optional_inner_type(&field.ty).is_some() {
        toasty_option_value_from_ref(field, value)
    } else {
        toasty_value_from_ref(field, value)
    }
}

fn toasty_owned_model_value(field: &ModelField, value: &str) -> String {
    if is_copy_filter_type(&field.ty)
        || optional_inner_type(&field.ty).is_some_and(is_copy_filter_type)
    {
        value.to_string()
    } else {
        format!("{value}.clone()")
    }
}

fn render_toasty_query_types(out: &mut String, model: &ModelSpec, pascal: &str) {
    use std::fmt::Write as _;

    writeln!(out, "#[derive(Clone, Copy, Debug, PartialEq, Eq)]").unwrap();
    writeln!(out, "pub enum {pascal}Order {{").unwrap();
    for field in model_order_fields(model) {
        let variant = to_pascal_case(&field.name);
        writeln!(out, "    {variant}Asc,").unwrap();
        writeln!(out, "    {variant}Desc,").unwrap();
    }
    writeln!(out, "}}").unwrap();
    writeln!(out).unwrap();

    writeln!(out, "#[derive(Clone, Debug)]").unwrap();
    writeln!(out, "pub enum {pascal}Predicate {{").unwrap();
    for field in model_query_fields(model) {
        let field_ty = &field.ty;
        if let Some(inner_ty) = optional_inner_type(field_ty) {
            writeln!(
                out,
                "    {}({inner_ty}),",
                predicate_variant_name(field, "Eq")
            )
            .unwrap();
            writeln!(
                out,
                "    {}({inner_ty}),",
                predicate_variant_name(field, "Ne")
            )
            .unwrap();
            writeln!(out, "    {},", predicate_variant_name(field, "IsNull")).unwrap();
            writeln!(out, "    {},", predicate_variant_name(field, "IsNotNull")).unwrap();
            writeln!(
                out,
                "    {}(Vec<{inner_ty}>),",
                predicate_variant_name(field, "In")
            )
            .unwrap();
            writeln!(
                out,
                "    {}(Vec<{inner_ty}>),",
                predicate_variant_name(field, "NotIn")
            )
            .unwrap();
            if is_numeric_type(inner_ty) {
                for suffix in ["Gt", "Gte", "Lt", "Lte"] {
                    writeln!(
                        out,
                        "    {}({inner_ty}),",
                        predicate_variant_name(field, suffix)
                    )
                    .unwrap();
                }
                writeln!(
                    out,
                    "    {}({inner_ty}, {inner_ty}),",
                    predicate_variant_name(field, "Between")
                )
                .unwrap();
            }
            if inner_ty == "String" {
                writeln!(
                    out,
                    "    {}(String),",
                    predicate_variant_name(field, "Contains")
                )
                .unwrap();
                writeln!(
                    out,
                    "    {}(String),",
                    predicate_variant_name(field, "NotContains")
                )
                .unwrap();
                writeln!(
                    out,
                    "    {}(String),",
                    predicate_variant_name(field, "IContains")
                )
                .unwrap();
                writeln!(
                    out,
                    "    {}(String),",
                    predicate_variant_name(field, "NotIContains")
                )
                .unwrap();
                writeln!(
                    out,
                    "    {}(String),",
                    predicate_variant_name(field, "EqualFold")
                )
                .unwrap();
                writeln!(
                    out,
                    "    {}(String),",
                    predicate_variant_name(field, "NotEqualFold")
                )
                .unwrap();
                writeln!(
                    out,
                    "    {}(String),",
                    predicate_variant_name(field, "StartsWith")
                )
                .unwrap();
                writeln!(
                    out,
                    "    {}(String),",
                    predicate_variant_name(field, "NotStartsWith")
                )
                .unwrap();
                writeln!(
                    out,
                    "    {}(String),",
                    predicate_variant_name(field, "EndsWith")
                )
                .unwrap();
                writeln!(
                    out,
                    "    {}(String),",
                    predicate_variant_name(field, "NotEndsWith")
                )
                .unwrap();
            }
        } else {
            writeln!(
                out,
                "    {}({field_ty}),",
                predicate_variant_name(field, "Eq")
            )
            .unwrap();
            writeln!(
                out,
                "    {}({field_ty}),",
                predicate_variant_name(field, "Ne")
            )
            .unwrap();
            writeln!(
                out,
                "    {}(Vec<{field_ty}>),",
                predicate_variant_name(field, "In")
            )
            .unwrap();
            writeln!(
                out,
                "    {}(Vec<{field_ty}>),",
                predicate_variant_name(field, "NotIn")
            )
            .unwrap();
            if is_numeric_type(field_ty) {
                for suffix in ["Gt", "Gte", "Lt", "Lte"] {
                    writeln!(
                        out,
                        "    {}({field_ty}),",
                        predicate_variant_name(field, suffix)
                    )
                    .unwrap();
                }
                writeln!(
                    out,
                    "    {}({field_ty}, {field_ty}),",
                    predicate_variant_name(field, "Between")
                )
                .unwrap();
            }
            if field_ty == "String" {
                writeln!(
                    out,
                    "    {}(String),",
                    predicate_variant_name(field, "Contains")
                )
                .unwrap();
                writeln!(
                    out,
                    "    {}(String),",
                    predicate_variant_name(field, "NotContains")
                )
                .unwrap();
                writeln!(
                    out,
                    "    {}(String),",
                    predicate_variant_name(field, "IContains")
                )
                .unwrap();
                writeln!(
                    out,
                    "    {}(String),",
                    predicate_variant_name(field, "NotIContains")
                )
                .unwrap();
                writeln!(
                    out,
                    "    {}(String),",
                    predicate_variant_name(field, "EqualFold")
                )
                .unwrap();
                writeln!(
                    out,
                    "    {}(String),",
                    predicate_variant_name(field, "NotEqualFold")
                )
                .unwrap();
                writeln!(
                    out,
                    "    {}(String),",
                    predicate_variant_name(field, "StartsWith")
                )
                .unwrap();
                writeln!(
                    out,
                    "    {}(String),",
                    predicate_variant_name(field, "NotStartsWith")
                )
                .unwrap();
                writeln!(
                    out,
                    "    {}(String),",
                    predicate_variant_name(field, "EndsWith")
                )
                .unwrap();
                writeln!(
                    out,
                    "    {}(String),",
                    predicate_variant_name(field, "NotEndsWith")
                )
                .unwrap();
            }
        }
    }
    writeln!(out, "    And(Vec<{pascal}Predicate>),").unwrap();
    writeln!(out, "    Or(Vec<{pascal}Predicate>),").unwrap();
    writeln!(out, "    Not(Box<{pascal}Predicate>),").unwrap();
    writeln!(out, "}}").unwrap();
    writeln!(out).unwrap();

    render_toasty_predicate_helpers(out, model, pascal);

    writeln!(out, "#[derive(Clone, Debug, Serialize, Deserialize)]").unwrap();
    writeln!(out, "pub struct {pascal}Page {{").unwrap();
    writeln!(out, "    pub items: Vec<{pascal}>,").unwrap();
    writeln!(out, "    pub total: u64,").unwrap();
    writeln!(out, "    pub page: u64,").unwrap();
    writeln!(out, "    pub page_size: u64,").unwrap();
    writeln!(out, "}}").unwrap();
    writeln!(out).unwrap();

    writeln!(out, "pub struct {pascal}Query<'a> {{").unwrap();
    writeln!(out, "    db: &'a mut dyn toasty::Executor,").unwrap();
    writeln!(out, "    predicates: Vec<{pascal}Predicate>,").unwrap();
    writeln!(out, "    orders: Vec<{pascal}Order>,").unwrap();
    writeln!(out, "    limit: Option<usize>,").unwrap();
    writeln!(out, "    offset: Option<usize>,").unwrap();
    writeln!(out, "    page: Option<(u64, u64)>,").unwrap();
    if model.soft_delete.is_some() {
        writeln!(out, "    include_deleted: bool,").unwrap();
    }
    writeln!(out, "}}").unwrap();
    writeln!(out).unwrap();
    render_toasty_query_builder_impl(out, model, pascal);
}

fn render_toasty_edge_methods(out: &mut String, model: &ModelSpec, pascal: &str) {
    use std::fmt::Write as _;

    if model.edges.is_empty() {
        return;
    }

    writeln!(out, "impl {pascal} {{").unwrap();
    for edge in &model.edges {
        let Some(field) = model.fields.iter().find(|field| field.name == edge.field) else {
            continue;
        };
        let method = edge_query_method_name(edge);
        let target_pascal = to_pascal_case(&edge.target);
        let target_module = to_snake_case(&edge.target);
        let ref_helper = predicate_helper_name_by_name(&edge.ref_field, "eq");
        writeln!(
            out,
            "    pub async fn {method}(&self, db: &mut dyn toasty::Executor) -> toasty::Result<Option<crate::model::{target_pascal}>> {{"
        )
        .unwrap();
        render_edge_value_binding(out, field);
        writeln!(
            out,
            "        crate::model::{target_pascal}Repository::query(db).where_(crate::model::{target_module}::{ref_helper}(value)).first().await"
        )
        .unwrap();
        writeln!(out, "    }}").unwrap();
        writeln!(out).unwrap();
    }
    writeln!(out, "}}").unwrap();
    writeln!(out).unwrap();
}

fn render_toasty_predicate_helpers(out: &mut String, model: &ModelSpec, pascal: &str) {
    use std::fmt::Write as _;

    for field in model_query_fields(model) {
        let field_ty = &field.ty;
        if let Some(inner_ty) = optional_inner_type(field_ty) {
            let eq = predicate_helper_name(field, "eq");
            let ne = predicate_helper_name(field, "ne");
            writeln!(
                out,
                "pub fn {eq}(value: {inner_ty}) -> {pascal}Predicate {{ {pascal}Predicate::{}(value) }}",
                predicate_variant_name(field, "Eq")
            )
            .unwrap();
            writeln!(
                out,
                "pub fn {ne}(value: {inner_ty}) -> {pascal}Predicate {{ {pascal}Predicate::{}(value) }}",
                predicate_variant_name(field, "Ne")
            )
            .unwrap();
            writeln!(
                out,
                "pub fn {}() -> {pascal}Predicate {{ {pascal}Predicate::{} }}",
                predicate_helper_name(field, "is_null"),
                predicate_variant_name(field, "IsNull")
            )
            .unwrap();
            writeln!(
                out,
                "pub fn {}() -> {pascal}Predicate {{ {pascal}Predicate::{} }}",
                predicate_helper_name(field, "is_not_null"),
                predicate_variant_name(field, "IsNotNull")
            )
            .unwrap();
            for (suffix, helper_suffix) in [("In", "in"), ("NotIn", "not_in")] {
                writeln!(
                    out,
                    "pub fn {}(values: Vec<{inner_ty}>) -> {pascal}Predicate {{ {pascal}Predicate::{}(values) }}",
                    predicate_helper_name(field, helper_suffix),
                    predicate_variant_name(field, suffix)
                )
                .unwrap();
            }
            if is_numeric_type(inner_ty) {
                for (suffix, helper_suffix) in
                    [("Gt", "gt"), ("Gte", "gte"), ("Lt", "lt"), ("Lte", "lte")]
                {
                    writeln!(
                        out,
                        "pub fn {}(value: {inner_ty}) -> {pascal}Predicate {{ {pascal}Predicate::{}(value) }}",
                        predicate_helper_name(field, helper_suffix),
                        predicate_variant_name(field, suffix)
                    )
                    .unwrap();
                }
                writeln!(
                    out,
                    "pub fn {}(start: {inner_ty}, end: {inner_ty}) -> {pascal}Predicate {{ {pascal}Predicate::{}(start, end) }}",
                    predicate_helper_name(field, "between"),
                    predicate_variant_name(field, "Between")
                )
                .unwrap();
            }
            if inner_ty == "String" {
                for (suffix, helper_suffix) in [
                    ("Contains", "contains"),
                    ("NotContains", "not_contains"),
                    ("IContains", "icontains"),
                    ("NotIContains", "not_icontains"),
                    ("EqualFold", "equal_fold"),
                    ("NotEqualFold", "not_equal_fold"),
                    ("StartsWith", "starts_with"),
                    ("NotStartsWith", "not_starts_with"),
                    ("EndsWith", "ends_with"),
                    ("NotEndsWith", "not_ends_with"),
                ] {
                    writeln!(
                        out,
                        "pub fn {}(value: impl Into<String>) -> {pascal}Predicate {{ {pascal}Predicate::{}(value.into()) }}",
                        predicate_helper_name(field, helper_suffix),
                        predicate_variant_name(field, suffix)
                    )
                    .unwrap();
                }
            }
        } else {
            for (suffix, helper_suffix) in [("Eq", "eq"), ("Ne", "ne")] {
                writeln!(
                    out,
                    "pub fn {}(value: {field_ty}) -> {pascal}Predicate {{ {pascal}Predicate::{}(value) }}",
                    predicate_helper_name(field, helper_suffix),
                    predicate_variant_name(field, suffix)
                )
                .unwrap();
            }
            for (suffix, helper_suffix) in [("In", "in"), ("NotIn", "not_in")] {
                writeln!(
                    out,
                    "pub fn {}(values: Vec<{field_ty}>) -> {pascal}Predicate {{ {pascal}Predicate::{}(values) }}",
                    predicate_helper_name(field, helper_suffix),
                    predicate_variant_name(field, suffix)
                )
                .unwrap();
            }
            if is_numeric_type(field_ty) {
                for (suffix, helper_suffix) in
                    [("Gt", "gt"), ("Gte", "gte"), ("Lt", "lt"), ("Lte", "lte")]
                {
                    writeln!(
                        out,
                        "pub fn {}(value: {field_ty}) -> {pascal}Predicate {{ {pascal}Predicate::{}(value) }}",
                        predicate_helper_name(field, helper_suffix),
                        predicate_variant_name(field, suffix)
                    )
                    .unwrap();
                }
                writeln!(
                    out,
                    "pub fn {}(start: {field_ty}, end: {field_ty}) -> {pascal}Predicate {{ {pascal}Predicate::{}(start, end) }}",
                    predicate_helper_name(field, "between"),
                    predicate_variant_name(field, "Between")
                )
                .unwrap();
            }
            if field_ty == "String" {
                for (suffix, helper_suffix) in [
                    ("Contains", "contains"),
                    ("NotContains", "not_contains"),
                    ("IContains", "icontains"),
                    ("NotIContains", "not_icontains"),
                    ("EqualFold", "equal_fold"),
                    ("NotEqualFold", "not_equal_fold"),
                    ("StartsWith", "starts_with"),
                    ("NotStartsWith", "not_starts_with"),
                    ("EndsWith", "ends_with"),
                    ("NotEndsWith", "not_ends_with"),
                ] {
                    writeln!(
                        out,
                        "pub fn {}(value: impl Into<String>) -> {pascal}Predicate {{ {pascal}Predicate::{}(value.into()) }}",
                        predicate_helper_name(field, helper_suffix),
                        predicate_variant_name(field, suffix)
                    )
                    .unwrap();
                }
            }
        }
    }
    writeln!(
        out,
        "pub fn and(predicates: Vec<{pascal}Predicate>) -> {pascal}Predicate {{ {pascal}Predicate::And(predicates) }}"
    )
    .unwrap();
    writeln!(
        out,
        "pub fn or(predicates: Vec<{pascal}Predicate>) -> {pascal}Predicate {{ {pascal}Predicate::Or(predicates) }}"
    )
    .unwrap();
    writeln!(
        out,
        "pub fn not(predicate: {pascal}Predicate) -> {pascal}Predicate {{ {pascal}Predicate::Not(Box::new(predicate)) }}"
    )
    .unwrap();
    for edge in &model.edges {
        let Some(field) = model.fields.iter().find(|field| field.name == edge.field) else {
            continue;
        };
        if edge.required || optional_inner_type(&field.ty).is_none() {
            continue;
        }
        let has = edge_has_helper_name(edge);
        let not_has = edge_not_has_helper_name(edge);
        let is_not_null = predicate_helper_name(field, "is_not_null");
        let is_null = predicate_helper_name(field, "is_null");
        writeln!(
            out,
            "pub fn {has}() -> {pascal}Predicate {{ {is_not_null}() }}"
        )
        .unwrap();
        writeln!(
            out,
            "pub fn {not_has}() -> {pascal}Predicate {{ {is_null}() }}"
        )
        .unwrap();
    }
    for field in model_order_fields(model) {
        let helper = model_field_ident(field);
        let variant = to_pascal_case(&field.name);
        writeln!(
            out,
            "pub fn {helper}_asc() -> {pascal}Order {{ {pascal}Order::{variant}Asc }}"
        )
        .unwrap();
        writeln!(
            out,
            "pub fn {helper}_desc() -> {pascal}Order {{ {pascal}Order::{variant}Desc }}"
        )
        .unwrap();
    }
    writeln!(out).unwrap();
}

fn render_toasty_model_query_method(out: &mut String, pascal: &str) {
    use std::fmt::Write as _;
    writeln!(out, "impl {pascal} {{").unwrap();
    writeln!(
        out,
        "    pub fn query(db: &mut dyn toasty::Executor) -> {pascal}Query<'_> {{"
    )
    .unwrap();
    writeln!(out, "        {pascal}Query::new(db)").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out, "}}").unwrap();
    writeln!(out).unwrap();
}

fn render_toasty_create_builder(out: &mut String, model: &ModelSpec, pascal: &str) {
    use std::fmt::Write as _;

    writeln!(out, "pub struct {pascal}Create<'a> {{").unwrap();
    writeln!(out, "    db: &'a mut dyn toasty::Executor,").unwrap();
    for field in model.fields.iter().filter(|field| !field.auto_increment) {
        let field_ident = model_field_ident(field);
        if let Some(inner_ty) = optional_inner_type(&field.ty) {
            writeln!(out, "    {field_ident}: Option<Option<{inner_ty}>>,").unwrap();
        } else {
            writeln!(out, "    {field_ident}: Option<{}>,", field.ty).unwrap();
        }
    }
    writeln!(out, "}}").unwrap();
    writeln!(out).unwrap();

    writeln!(out, "impl<'a> {pascal}Create<'a> {{").unwrap();
    writeln!(
        out,
        "    pub fn new(db: &'a mut dyn toasty::Executor) -> Self {{"
    )
    .unwrap();
    writeln!(out, "        Self {{").unwrap();
    writeln!(out, "            db,").unwrap();
    for field in model.fields.iter().filter(|field| !field.auto_increment) {
        writeln!(out, "            {}: None,", model_field_ident(field)).unwrap();
    }
    writeln!(out, "        }}").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();

    for field in model.fields.iter().filter(|field| !field.auto_increment) {
        let field_ident = model_field_ident(field);
        let setter = create_setter_name(field);
        if let Some(inner_ty) = optional_inner_type(&field.ty) {
            writeln!(
                out,
                "    pub fn {setter}(mut self, value: Option<{inner_ty}>) -> Self {{"
            )
            .unwrap();
        } else {
            writeln!(
                out,
                "    pub fn {setter}(mut self, value: {}) -> Self {{",
                field.ty
            )
            .unwrap();
        }
        writeln!(out, "        self.{field_ident} = Some(value);").unwrap();
        writeln!(out, "        self").unwrap();
        writeln!(out, "    }}").unwrap();
        writeln!(out).unwrap();
    }
    render_optional_clear_methods(
        out,
        model.fields.iter().filter(|field| !field.auto_increment),
    );
    render_toasty_edge_builder_setters(out, model, true);

    writeln!(
        out,
        "    pub async fn save(self) -> toasty::Result<{pascal}> {{"
    )
    .unwrap();
    let validation_fields = model
        .fields
        .iter()
        .filter(|field| !field.auto_increment)
        .collect::<Vec<_>>();
    render_field_validation_checks(out, &validation_fields, "toasty");
    writeln!(out, "        let mut create = {pascal}::create();").unwrap();
    for field in model.fields.iter().filter(|field| !field.auto_increment) {
        let field_ident = model_field_ident(field);
        if optional_inner_type(&field.ty).is_some() {
            if let Some(default_expr) = create_default_value_expr(field) {
                writeln!(
                    out,
                    "        if let Some(value) = self.{field_ident} {{ create = create.{field_ident}(value); }} else {{ create = create.{field_ident}({default_expr}); }}"
                )
                .unwrap();
            } else if field.default_value.is_some() {
                writeln!(
                    out,
                    "        if let Some(value) = self.{field_ident} {{ create = create.{field_ident}(value); }}"
                )
                .unwrap();
            } else {
                writeln!(
                    out,
                    "        create = create.{field_ident}(self.{field_ident}.unwrap_or(None));"
                )
                .unwrap();
            }
        } else if let Some(default_expr) = create_default_value_expr(field) {
            writeln!(
                out,
                "        if let Some(value) = self.{field_ident} {{ create = create.{field_ident}(value); }} else {{ create = create.{field_ident}({default_expr}); }}"
            )
            .unwrap();
        } else if field.default_value.is_some() {
            writeln!(
                out,
                "        if let Some(value) = self.{field_ident} {{ create = create.{field_ident}(value); }}"
            )
            .unwrap();
        } else {
            writeln!(
                out,
                "        let {field_ident} = self.{field_ident}.ok_or_else(|| toasty::Error::invalid_record_count(\"missing required field `{field_ident}` for {pascal} create\"))?;"
            )
            .unwrap();
            writeln!(out, "        create = create.{field_ident}({field_ident});").unwrap();
        }
    }
    writeln!(out, "        create.exec(self.db).await").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out, "}}").unwrap();
    writeln!(out).unwrap();
}

fn render_toasty_edge_builder_setters(out: &mut String, model: &ModelSpec, is_create: bool) {
    use std::fmt::Write as _;

    for edge in &model.edges {
        let Some(field) = model.fields.iter().find(|field| field.name == edge.field) else {
            continue;
        };
        if field.auto_increment || (!is_create && (field.name == model.primary || field.immutable))
        {
            continue;
        }
        let setter = create_setter_name_by_name(&edge.name);
        let target_pascal = to_pascal_case(&edge.target);
        let ref_ident = model_field_ident_by_name(&edge.ref_field);
        let value = edge_builder_value_expr(field, &format!("target.{ref_ident}"));
        writeln!(
            out,
            "    pub fn {setter}(mut self, target: &crate::model::{target_pascal}) -> Self {{"
        )
        .unwrap();
        writeln!(
            out,
            "        self.{} = Some({value});",
            model_field_ident(field)
        )
        .unwrap();
        writeln!(out, "        self").unwrap();
        writeln!(out, "    }}").unwrap();
        writeln!(out).unwrap();
        if !edge.required && optional_inner_type(&field.ty).is_some() && edge.name != field.name {
            let clear = rust_identifier(&format!("clear_{}", edge.name));
            writeln!(out, "    pub fn {clear}(mut self) -> Self {{").unwrap();
            writeln!(
                out,
                "        self.{} = Some(None);",
                model_field_ident(field)
            )
            .unwrap();
            writeln!(out, "        self").unwrap();
            writeln!(out, "    }}").unwrap();
            writeln!(out).unwrap();
        }
    }
}

fn render_toasty_update_builder(
    out: &mut String,
    model: &ModelSpec,
    pascal: &str,
    primary: &str,
    primary_ty: &str,
) {
    use std::fmt::Write as _;

    let primary_ident = rust_identifier(primary);
    writeln!(out, "pub struct {pascal}Update<'a> {{").unwrap();
    writeln!(out, "    db: &'a mut dyn toasty::Executor,").unwrap();
    writeln!(out, "    {primary_ident}: {primary_ty},").unwrap();
    for field in updatable_model_fields(model, primary) {
        let field_ident = model_field_ident(field);
        if let Some(inner_ty) = optional_inner_type(&field.ty) {
            writeln!(out, "    {field_ident}: Option<Option<{inner_ty}>>,").unwrap();
        } else {
            writeln!(out, "    {field_ident}: Option<{}>,", field.ty).unwrap();
        }
    }
    writeln!(out, "}}").unwrap();
    writeln!(out).unwrap();

    writeln!(out, "impl<'a> {pascal}Update<'a> {{").unwrap();
    writeln!(
        out,
        "    pub fn new(db: &'a mut dyn toasty::Executor, {primary_ident}: {primary_ty}) -> Self {{"
    )
    .unwrap();
    writeln!(out, "        Self {{").unwrap();
    writeln!(out, "            db,").unwrap();
    writeln!(out, "            {primary_ident},").unwrap();
    for field in updatable_model_fields(model, primary) {
        writeln!(out, "            {}: None,", model_field_ident(field)).unwrap();
    }
    writeln!(out, "        }}").unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out).unwrap();

    for field in updatable_model_fields(model, primary) {
        let field_ident = model_field_ident(field);
        let setter = create_setter_name(field);
        if let Some(inner_ty) = optional_inner_type(&field.ty) {
            writeln!(
                out,
                "    pub fn {setter}(mut self, value: Option<{inner_ty}>) -> Self {{"
            )
            .unwrap();
        } else {
            writeln!(
                out,
                "    pub fn {setter}(mut self, value: {}) -> Self {{",
                field.ty
            )
            .unwrap();
        }
        writeln!(out, "        self.{field_ident} = Some(value);").unwrap();
        writeln!(out, "        self").unwrap();
        writeln!(out, "    }}").unwrap();
        writeln!(out).unwrap();
    }
    render_optional_clear_methods(out, updatable_model_fields(model, primary));
    render_toasty_edge_builder_setters(out, model, false);

    writeln!(
        out,
        "    pub async fn save(self) -> toasty::Result<{pascal}> {{"
    )
    .unwrap();
    let validation_fields = updatable_model_fields(model, primary);
    render_field_validation_checks(out, &validation_fields, "toasty");
    writeln!(
        out,
        "        let mut model = {pascal}::get_by_{primary}(self.db, &self.{primary_ident}).await?;"
    )
    .unwrap();
    for field in updatable_model_fields(model, primary) {
        let field_ident = model_field_ident(field);
        writeln!(
            out,
            "        if let Some(value) = self.{field_ident} {{ model.{field_ident} = value; }}"
        )
        .unwrap();
    }
    let update_default_fields = updatable_model_fields(model, primary);
    render_update_default_assignments(out, &update_default_fields, "toasty-model");
    writeln!(
        out,
        "        {pascal}Repository::update(self.db, model).await"
    )
    .unwrap();
    writeln!(out, "    }}").unwrap();
    writeln!(out, "}}").unwrap();
    writeln!(out).unwrap();
}

