    writeln!(out, "            orders: Vec::new(),").unwrap();
    writeln!(out, "            limit: None,").unwrap();
    writeln!(out, "            offset: None,").unwrap();
    writeln!(out, "            page: None,").unwrap();
    if model.soft_delete.is_some() {
        writeln!(out, "            include_deleted: false,").unwrap();
    }
    writeln!(out, "        }}").unwrap();
    writeln!(out, "    }}").unwrap();
