        assert_eq!(model.cache_prefix.as_deref(), Some("acct"));
        assert_eq!(model.cache_ttl_secs, Some(600));
        assert_eq!(model.negative_cache_ttl_secs, Some(30));
        assert_eq!(model.tenant.as_deref(), Some("tenant_id"));
